const s={"abhinandannath-chalisa":{id:"abhinandannath-chalisa",category:"chalisa",title:"श्री अभिनंदननाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["ऋषभ अजित सम्भव अभिनंदन, दया करे सब पर दुखभंजन।"]},{lines:["जनम-मरन के टूटें बंधन, मनमंदिर तिष्ठें अभिनंदन।।"]},{lines:["॥ चौपाई ॥"]},{lines:["अयोध्या नगरी अति सुंदर, करते राज्य भूपति संवर।"]},{lines:["सिद्धार्था उनकी महारानी, सुंदरता में थी लासानी।"]},{lines:["रानी ने देखे शुभ सपने, बरसे रतन महल के अंगने।"]},{lines:["मुख में देखा हस्ति समाता, कहलाई तीर्थंकर माता।"]},{lines:["जननी उदर प्रभु अवतारे, स्वर्गों से आए सुर सारे।"]},{lines:["मात-पिता की पूजा करते, गर्भ कल्याणक उत्सव करते।"]},{lines:["द्वादशी माघ शुक्ल की आई, जनमें अभिनंदन जिनराई।"]},{lines:["देवों के भी आसन कांपे, शिशु को ले गए मेरु पे।"]},{lines:["नहवन किया शत आठ कलशों से, अभिनंदन कहा प्रेम भाव से।"]},{lines:["सूर्य समान प्रभु तेजस्वी, हुए जगत में महा यशस्वी।"]},{lines:["बोले हित-मित वचन सुबोध, वाणी में कहीं नहीं विरोध।"]},{lines:["यौवन से जब हुए विभूषित, राज्यश्री को किया सुशोभित।"]},{lines:["साढ़े तीन सौ धनुष प्रमाण, उन्नत प्रभु तन शोभवान।"]},{lines:["परणाई कन्याएं अनेक, लेकिन छोड़ा नहीं विवेक।"]},{lines:["नित प्रति नूतन भोग भोगते, जल में भिन्न कमल सम रहते।"]},{lines:["एक दिन देखे मेघ अंबर में, मेघ महल बनते पल में।"]},{lines:["हुए विलीन पवन के चलने से, उदासीन हो गए जगत से।"]},{lines:["राज पाठ निज सुत को सौपा, मन में समता वृक्ष को रोपा।"]},{lines:["गए उग्र नामक उद्यान, दीक्षित हुए वहां गुणखान।"]},{lines:["शुक्ला द्वादशी थी माघ मास, दो दिन धारा उपवास।"]},{lines:["तीसरे दिन फिर किया विहार, इंद्रदत्त नृप ने दिया आहार।"]},{lines:["वर्ष अठारह किया घोर तप, सहे शीत वर्षा और आतप।"]},{lines:["एक दिन आसन वृक्ष के नीचे, ध्यान वृष्टि से आत्म सींचे।"]},{lines:["उदय हुआ केवल दिनकर का, लोकालोक ज्ञान में झलक।"]},{lines:["हुई तब समोशरण की रचना, खीरी प्रभु की दिव्य देशना।"]},{lines:["जीवाजीव और धर्माधर्म, आकाश काल षटद्रव्य मर्म।"]},{lines:["जीव द्रव्य ही सार भूत है, स्वयं सिद्धि ही परम पूत है।"]},{lines:["रूप तीन लोक समझाया, ऊर्ध्व मध्य अधोलोक बताया।"]},{lines:["नीचे नरक बताए सात, भुगते पापी अपने पाप।"]},{lines:["ऊपर सोलह स्वर्ग सुजान, चतुर निकाय देव विमान।"]},{lines:["मध्य लोक में द्वीप असंख्य, ढाई द्वीप में जाए भव्य।"]},{lines:["भटकों को सन्मार्ग दिखाया, भव्यों को भव पार लगाया।"]},{lines:["पहुंचे गण सम्मेद अंत में, प्रतिमा योग धरा एकांत में।"]},{lines:["शुक्ल ध्यान में लीन हुए तब, कर्म प्रकृति क्षीण हुई सब।"]},{lines:["बैसाख शुक्ल षष्ठी पुण्यवान, प्रात: प्रभु का हुआ निर्वाण।"]},{lines:["मोक्ष कल्याणक करे सुर आकर, आनंदकूट पूजे हर्षकर।"]},{lines:["चालीसा श्री जिन अभिनंदन, दूर करें सबके भवक्रंदन।"]},{lines:["स्वामी तुम हो पापनिकंदन, अरुणा करती शत शत वंदन।"]}]},"adinath-chalisa":{id:"adinath-chalisa",category:"chalisa",title:"श्री आदिनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","उपाध्याय आचार्य का ले सुखकारी नाम ॥","सर्व साधु और सरस्वती, जिन मन्दिर सुखकार।","आदिनाथ भगवान को, मन मन्दिर में धार ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जै जै आदिनाथ जिन स्वामी, तीनकाल तिहूं जग में नामी ।","वेष दिगम्बर धार रहे हो, कर्मों को तुम मार रहे हो ॥","हो सर्वज्ञ बात सब जानो, सारी दुनियां को पहचानो ।","नगर अयोध्या जो कहलाये, राजा नाभिराज बतलाये ॥"]},{lines:["मरुदेवी माता के उदर से, चैत वदी नवमी को जन्मे ।","तुमने जग को ज्ञान सिखाया, कर्मभूमी का बीज उपाया ॥","कल्पवृक्ष जब लगे बिछरने, जनता आई दुखड़ा कहने ।","सब का संशय तभी भगाया, सूर्य चन्द्र का ज्ञान कराया ॥"]},{lines:["खेती करना भी सिखलाया, न्याय दण्ड आदिक समझाया ।","तुमने राज किया नीति का, सबक आपसे जग ने सीखा ॥","पुत्र आपका भरत बताया, चक्रवर्ती जग में कहलाया ।","बाहुबली जो पुत्र तुम्हारे, भरत से पहले मोक्ष सिधारे ॥"]},{lines:["सुता आपकी दो बतलाई, ब्राह्मी और सुन्दरी कहलाई ।","उनको भी विद्या सिखलाई, अक्षर और गिनती बतलाई ॥","एक दिन राजसभा के अंदर, एक अप्सरा नाच रही थी ।","आयु उसकी बहुत अल्प थी, इसलिए आगे नहीं नाच सकी थी ॥"]},{lines:["विलय हो गया उसका सत्वर, झट आया वैराग्य उमड़कर ।","बेटो को झट पास बुलाया, राजपाट सब में बंटवाया ॥","छोड़ सभी झंझट संसारी, वन जाने की करी तैयारी ।","राजा हजारों साथ सिधाए, राजपाट तज वन को धाये ॥"]},{lines:["लेकिन जब तुमने तप कीना, सबने अपना रस्ता लीना ।","वेष दिगम्बर तजकर सबने, छाल आदि के कपड़े पहने ॥","भूख प्यास से जब घबराये, फल आदिक खा भूख मिटाये ।","तीन सौ त्रेसठ धर्म फैलाये, जो अब दुनियां में दिखलाये ॥"]},{lines:["छै: महीने तक ध्यान लगाये, फिर भोजन करने को धाये ।","भोजन विधि जाने नहि कोय, कैसे प्रभु का भोजन होय ॥","इसी तरह बस चलते चलते, छः महीने भोजन बिन बीते ।","नगर हस्तिनापुर में आये, राजा सोम श्रेयांस बताए ॥"]},{lines:["याद तभी पिछला भव आया, तुमको फौरन ही पड़धाया ।","रस गन्ने का तुमने पाया, दुनिया को उपदेश सुनाया ॥","तप कर केवल ज्ञान पाया, मोक्ष गए सब जग हर्षाया ।","अतिशय युक्त तुम्हारा मन्दिर, चाँदखेड़ी भंवरे के अंदर ॥"]},{lines:["उसका यह अतिशय बतलाया, कष्ट क्लेश का होय सफाया ।","मानतुंग पर दया दिखाई, जंजीरें सब काट गिराई ॥","राजसभा में मान बढ़ाया, जैन धर्म जग में फैलाया ।","मुझ पर भी महिमा दिखलाओ, कष्ट भक्त का दूर भगाओ ॥"]},{lines:["॥ सोरठा ॥"]},{lines:["पाठ करे चालीस दिन, नित चालीस ही बार ।","चाँदखेड़ी में आय के, खेवे धूप अपार ॥","जन्म दरिद्री होय जो, होय कुबेर समान ।","नाम वंश जग में चले, जिनके नहीं संतान ॥"]}]},"ajitnath-chalisa":{id:"ajitnath-chalisa",category:"chalisa",title:"श्री अजितनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["अष्टकर्म को नाशकर, बने सिद्ध भगवान।"]},{lines:["उनके चरणों में करूँ, शत-शत बार प्रणाम।।"]},{lines:["पुन: सरस्वती मात को, ज्ञानप्राप्ति के हेतु।"]},{lines:["नमन करूँ सिर नाय के, श्रद्धा भक्ति समेत।।"]},{lines:["अजितनाथ भगवान ने, जीते विषय-कषाय।"]},{lines:["उनकी गुणगाथा कहूँ, पद अजेय मिल जाय।।"]},{lines:["॥ चौपाई ॥"]},{lines:["श्री आदिनाथ को शीश नवाकर, माता सरस्वती को ध्याय।"]},{lines:["शुरू करूँ श्री अजितनाथ का, चालीसा स्व-पर सुखदाय।।"]},{lines:["जय श्री अजितनाथ जिनराज, पावन चिह्न धरें 'गजराज'।"]},{lines:["नगर अयोध्या करते राज, जितशत्रु नामक महाराज।।"]},{lines:["विजयसेना उनकी महारानी, देखें सोलह स्वप्न ललामी।"]},{lines:["दिव्य विमान विजय से चयकर, जननी उदर बसे प्रभु आकर।।"]},{lines:["शुक्ला दशमी माघ मास की, जन्म जयन्ती अजित नाथ की।"]},{lines:["इन्द्र प्रभु को शीशधार कर, गए सुमेरु हर्षित होकर।।"]},{lines:["नीर क्षीर सागर से लाकर, न्हवन करें भक्ति में भरकर।"]},{lines:["वस्त्राभूषण दिव्य पहनाए, वापस लौट अयोध्या आए।।"]},{lines:["अजितनाथ की शोभा न्यारी, वर्ण स्वर्ण सम कान्तिधारी।"]},{lines:["बीता बचपन जब हितकारी, हुआ ब्याह तब मंगलकारी।।"]},{lines:["कर्मबन्ध नहीं हो भोगों में, अन्तर्दृष्टि थी योगों में।"]},{lines:["चंचल चपला देखी नभ में, हुआ वैराग्य निरन्तर मन में।।"]},{lines:["राजपाट निज सुत को देकर, हुए दिगम्बर दीक्षा लेकर।"]},{lines:["छ: दिन बाद हुआ आहार, करें श्रेष्ठि ब्रह्मा सत्कार।।"]},{lines:["किये पंच अचरज देवों ने, पुण्योपार्जन किया सभी ने।"]},{lines:["बारह वर्ष तपस्या कीनी, दिव्यज्ञान की सिद्धि नवीनी।।"]},{lines:["धनपति ने इन्द्राज्ञा पाकर, रच दिया समोशरण हर्षाकर।"]},{lines:["सभा विशाल लगी जिनवर की, दिव्यध्वनि खिरती प्रभुवर की।।"]},{lines:["वाद – विवाद मिटाने हेतु, अनेकान्त का बाँधा सेतु।"]},{lines:["हैं सापेक्ष यहाँ सब तत्व, अन्योन्याश्रित है उन सत्व।।"]},{lines:["सब जीवों में हैं जो आतम, वे भी हो सकते शुद्धात्म।"]},{lines:["ध्यान अग्नि का ताप मिले जब, केवल ज्ञान की ज्योति जले तब।।"]},{lines:["मोक्ष मार्ग तो बहुत सरल है, लेकिन राही हुए विरल हैं।"]},{lines:["हीरा तो सब ले नहीं पावें, सब्जी-भाजी भीड़ धरावें।।"]},{lines:["दिव्यध्वनि सुन कर जिनवर की, खिली कली जन-जन के मन की।","प्राप्ति कर सम्यग्दर्शन की, बगिया महकी भव्य जनों की।।"]},{lines:["हिंसक पशु भी समता धारें, जन्म-जन्म का बैर निवारें।"]},{lines:["पूर्ण प्रभावना हुई धर्म की, भावना शुद्ध हुई भविजन की।।"]},{lines:["दूर-दूर तक हुआ विहार, सदाचार का हुआ प्रचार।"]},{lines:["एक माह की उम्र रही जब, गए शिखर सम्मेद प्रभु तब।।"]},{lines:["अखण्ड मौन मुद्रा की धारण, कर्म अघाति हेतु निवारण।"]},{lines:["शुक्ल ध्यान का हुआ प्रताप, लोक शिखर पर पहुँचे आप।।"]},{lines:["'सिद्धवर कूट' की भारी महिमा, गाते सब प्रभु की गुण-गरिमा।"]},{lines:["विजित किए श्री अजित ने, अष्ट कर्म बलवान।"]},{lines:["निहित आत्मगुण अमित हैं, 'अरुणा' सुख की खान।।"]},{lines:["(जाप – ॐ ह्रीं अर्हं श्री अजितनाथाय नमः)"]}]},"anantnath-chalisa":{id:"anantnath-chalisa",category:"chalisa",title:"श्री अनन्तनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["श्री अनन्त जिनराज हैं, गुण अनन्त की खान।"]},{lines:["अंतक का भी अंत कर, बने सिद्ध भगवान॥"]},{lines:["गुण अनन्त की प्राप्ति हित, करूँ अनन्त प्रणाम।"]},{lines:["अनन्त गुणाकर नाथ! तुम, कर दो मम कल्याण॥"]},{lines:["विदुषी वागीश्वरी यदि, दे दें आशिर्वाद।"]},{lines:["पूरा होवे शीघ्र ही, यह चालीसा पाठ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["अनन्त चतुष्टय धारी 'अनन्त', अनन्त गुणों की खान 'अनन्त'。"]},{lines:["सर्वशुद्ध ज्ञायक हैं अनन्त, हरण करें मम दोष अनन्त。"]},{lines:["नगर अयोध्या महा सुखकार, राज्य करें सिंहसेन अपार。"]},{lines:["सर्वयशा महादेवी उनकी, जननी कहलाई जिनवर की。"]},{lines:["द्वादशी ज्येष्ठ कृष्ण सुखकारी, जन्मे तीर्थंकर हितकारी。"]},{lines:["इन्द्र प्रभु को गोद में लेकर, न्हवन करें मेरु पर जाकर。"]},{lines:["नाम 'अनन्तनाथ' शुभ दीना, उत्सव करते नित्य नवीना。"]},{lines:["सार्थक हुआ नाम प्रभुवर का, पार नहीं गुण के सागर का。"]},{lines:["वर्ण सुवर्ण समान प्रभु का, ज्ञान धरें मति-श्रुत-अवधि का。"]},{lines:["आयु तीस लख वर्ष उपाई, धनुष अर्धशत तन ऊंचाई。"]},{lines:["बचपन गया जवानी आई, राज्य मिला उनको सुखदाई。"]},{lines:["हुआ विवाह उनका मंगलमय, जीवन था जिनवर का सुखमय。"]},{lines:["पन्द्रह लाख बरस बीते जब, उल्कापात से हुए विरत तब。"]},{lines:["जग में सुख पाया किसने-कब, मन से त्याग राग भाव सब。"]},{lines:["बारह भावना मन में भाये, ब्रह्मर्षि वैराग्य बढ़ाये。"]},{lines:["'अनन्तविजय' सुत तिलक कराकर, देवोमई शिविका पधरा कर。"]},{lines:["गए सहेतुक वन जिनराज, दीक्षित हुए सहस नृप साथ。"]},{lines:["द्वादशी कृष्ण ज्येष्ठ शुभ मास, तीन दिन का धारा उपवास。"]},{lines:["गए अयोध्या प्रथम योग कर, धन्य 'विशाख' आहार करा कर。"]},{lines:["मौन सहित रहते थे वन में, एक दिन तिष्ठे पीपल-तल में。"]},{lines:["अटल रहे निज योग ध्यान में, झलके लोकालोक ज्ञान में。"]},{lines:["कृष्ण अमावस चैत्र मास की, रचना हुई शुभ समवशरण की。"]},{lines:["जिनवर की वाणी जब खिरती, अमृत सम कानों को लगती。"]},{lines:["चतुर्गति दुख चित्रण करते, भविजन सुन पापों से डरते。"]},{lines:['"जो चाहो तुम मुक्ति पाना, निज आतम की शरण में जाना。']},{lines:["सम्यग्दर्शन-ज्ञान-चरित हैं, कहे व्यवहार में रतनत्रय हैं。"]},{lines:["निश्चय से शुद्धातम ध्याकर, शिवपद मिलता सुख रत्नाकर。"]},{lines:["श्रद्धा करके भव्य जनों ने, यथाशक्ति व्रत धारे सबने。"]},{lines:["हुआ विहार देश और प्रान्त, सत्पथ दर्शायें जिननाथ。"]},{lines:["अन्त समय गए सम्मेदाचल, एक मास तक रहे सुनिश्चल。"]},{lines:["कृष्ण चैत्र अमावस पावन, मोक्षमहल पहुँचे मनभावन。"]},{lines:["उत्सव करते सुरगण आकर, कूट स्वयंप्रभ मन में ध्याकर。"]},{lines:["शुभ लक्षण प्रभुवर का 'सेही', शोभित होता प्रभु-पद में ही。"]},{lines:["'अरुणा' अरज करे बस ये ही, पार करो भवसागर से ही。"]},{lines:["हे प्रभु लोकालोक अनन्त, झलकें सब तुम ज्ञान अनन्त。"]},{lines:["हुआ अनन्त भवों का अन्त, अद्भुत तुम महिमा है 'अनन्त'。"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री अनन्तनाथाय नमः)"]}]},"aranath-chalisa":{id:"aranath-chalisa",category:"chalisa",title:"श्री अरहनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["अरहनाथ भगवान हैं, तीनलोक के नाथ।"]},{lines:["ध्यानचक्र से मृत्यु को, किया पराजित आप।।"]},{lines:["हस्तिनापुर तीर्थ पर, हुए चार कल्याण।"]},{lines:["गर्भ-जन्म-तप और है, चौथा केवलज्ञान।।"]},{lines:["अरहनाथ तीर्थेश भी, त्रयपदवीयुत नाथ।"]},{lines:["तीर्थंकर-चक्री तथा कामदेव जगमान्य।।"]},{lines:["इनके ही गुणगान में, यह चालीसा पाठ।"]},{lines:["लिखने की इच्छा हुई, कृपा करो श्रुतमात।।"]},{lines:["॥ चौपाई ॥"]},{lines:["श्री अरहनाथ जिनेन्द्र गुणाकर, ज्ञान-दरस-सुरव-बल रत्ऩाकर。"]},{lines:["कल्पवृक्ष सम सुख के सागर, पार हुए निज आत्म ध्याकर。"]},{lines:["अरहनाथ नाथ वसु अरि के नाशक, हुए हस्तिनापुर के शासक。"]},{lines:["माँ मित्रसेना पिता सुदर्शन, चक्रवर्ती बन किया दिग्दर्शन。"]},{lines:["सहस चौरासी आयु प्रभु की, अवगाहना थी तीस धनुष की。"]},{lines:["वर्ण सुवर्ण समान था पीत, रोग शोक थे तुमसे भीत。"]},{lines:["ब्याह हुआ जब प्रिय कुमार का, स्वप्न हुआ साकार पिता का。"]},{lines:["राज्याभिषेक हुआ अरहजिन का, हुआ अभ्युदय चक्र रत्न का।।"]},{lines:["एक दिन देखा शरद ऋतु में, मेघ विलीन हुए क्षण भर में。"]},{lines:["उदित हुआ वैराग्य हृदय में, तौकान्तिक सुर आए पल में。"]},{lines:["'अरविन्द' पुत्र को देकर राज, गए सहेतुक वन जिनराज。"]},{lines:["मंगसिर की दशमी उजियारी, परम दिगम्बर दीक्षाधारी。"]},{lines:["पंचमुष्टि उखाड़े केश, तन से ममत्व रहा नहीं दलेश。"]},{lines:["नगर चक्रपुर गए पारण हित, पढ़गाहें भूपति अपराजित。"]},{lines:["प्रासुक शुद्धाहार कराये, पंचाश्चर्य देव कराये。"]},{lines:["कठिन तपस्या करते वन में, लीन रहें आत्म चिन्तन में。"]},{lines:["कार्तिक मास द्वादशी उज्जवल, प्रभु विराज्ञे आम्र वृक्ष- तल。"]},{lines:["अन्तर ज्ञान ज्योति प्रगटाई, हुए केवली श्री जिनराई。"]},{lines:["देव करें उत्सव अति भव्य, समोशरण को रचना दिव्य。"]},{lines:["सोलह वर्ष का मौनभंग कर, सप्तभंग जिनवाणी सुखकर。"]},{lines:["चौदह गुणस्थान बताये, मोह – काय-योग दर्शाये。"]},{lines:["सत्तावन आश्रव बतलाये, इतने ही संवर गिनवाये。"]},{lines:["संवर हेतु समता लाओ, अनुप्रेक्षा द्वादश मन भाओ。"]},{lines:["हुए प्रबुद्ध सभी नर- नारी, दीक्षा व्रत धरि बहु भारी。"]},{lines:["कुम्भार्प आदि गणधर तीस, अर्द्ध लक्ष थे सकल मुनीश。"]},{lines:["सत्यधर्म का हुआ प्रचार, दूर-दूर तक हुआ विहार。"]},{lines:["एक माह पहले निर्वेद, सहस मुनिसंग गए सम्मेद。"]},{lines:["चैत्र कृष्ण एकादशी के दिन, मोक्ष गए श्री अरहनाथ जिन。"]},{lines:["नाटक कूट को पूजे देव, कामदेव-चक्री…जिनदेव。"]},{lines:["जिनवर का लक्षण था मीन, धारो जैन धर्म समीचीन。"]},{lines:["प्राणी मात्र का जैन धर्मं है, जैन धर्म ही परम धर्मं हैं。"]},{lines:["पंचेन्द्रियों को जीतें जो नर, जिनेन्द्रिय वे बनते जिनवर。"]},{lines:["त्याग धर्म की महिमा गाई, त्याग में ही सब सुख हों भाई。"]},{lines:["त्याग कर सकें केवल मानव, हैं सक्षम सब देव और मानव。"]},{lines:["हो स्वाधीन तजो तुम भाई, बन्धन में पीडा मन लाई。"]},{lines:["हस्तिनापुर में दूसरी नशिया, कर्म जहाँ पर नसे घातिया。"]},{lines:["जिनके चरणों में धरें, शीश सभी नरनाथ。"]},{lines:["हम सब पूजे उन्हें, कृपा करें अरहनाथ。"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री अरहनाथाय नमः)"]}]},"chandraprabhu-chalisa":{id:"chandraprabhu-chalisa",category:"chalisa",title:"श्री चन्द्रप्रभु चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["वीतराग सर्वज्ञ जिन, जिनवाणी को ध्याय |","लिखने का साहस करुं, चालीसा सिर नाय ||","देहरे के श्रीचन्द्र को, पूजौं मन वच काय |","ऋद्धि सिद्धि मंगल करें, विघ्न दूर हो जाय ||"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्रीचन्द्र दया के सागर, देहरे वाले ज्ञान उजागर ||","शांति छवि मूरति अति प्यारी, भेष दिगम्बर धारा भारी ||","नासा पर है दृष्टि तुम्हारी, मोहनी मूरति कितनी प्यारी ||","देवों के तुम देव कहावो, कष्ट भक्त के दूर हटावो ||"]},{lines:["समन्तभद्र मुनिवर ने ध्याया, पिंडी फटी दर्श तुम पाया ||","तुम जग में सर्वज्ञ कहावो, अष्टम तीर्थंकर कहलावो ||","महासेन के राजदुलारे, मात सुलक्षणा के हो प्यारे ||","चन्द्रपुरी नगरी अति नामी, जन्म लिया चन्द्र-प्रभु स्वामी ||"]},{lines:["पौष वदी ग्यारस को जन्मे, नर नारी हरषे तब मन में ||","काम क्रोध तृष्णा दुखकारी, त्याग सुखद मुनि दीक्षा धारी ||","फाल्गुन वदी सप्तमी भाई, केवल ज्ञान हुआ सुखदाई ||","फिर सम्मेद शिखर पर जाके, मोक्ष गये प्रभु आप वहां से ||"]},{lines:["लोभ मोह और छोड़ी माया, तुमने मान कषाय नसाया ||","रागी नहीं, नहीं तू द्वेषी, वीतराग तू हित उपदेशी ||","पंचम काल महा दुखदाई, धर्म कर्म भूले सब भाई ||","अलवर प्रान्त में नगर तिजारा, होय जहां पर दर्शन प्यारा ||"]},{lines:["उत्तर दिशि में देहरा माहीं, वहां आकर प्रभुता प्रगटाई ||","सावन सुदि दशमि शुभ नामी, प्रकट भये त्रिभुवन के स्वामी ||","चिह्न चन्द्र का लख नर नारी, चंद्रप्रभु की मूरती मानी ||","मूर्ति आपकी अति उजयाली, लगता हीरा भी है जाली ||"]},{lines:["अतिशय चन्द्र प्रभु का भारी, सुनकर आते यात्री भारी ||","फाल्गुन सुदी सप्तमी प्यारी, जुड़ता है मेला यहां भारी ||","कहलाने को तो शशि धर हो, तेज पुंज रवि से बढ़कर हो ||","नाम तुम्हारा जग में सांचा, ध्यावत भागत भूत पिशाचा ||"]},{lines:["राक्षस भूत प्रेत सब भागें, तुम सुमिरत भय कभी न लागे ||","कीर्ति तुम्हारी है अति भारी, गुण गाते नित नर और नारी ||","जिस पर होती कृपा तुम्हारी, संकट झट कटता ही भारी ||","जो भी जैसी आश लगाता, पूरी उसे तुरत कर पाता ||"]},{lines:["दुखिया दर पर जो आते हैं, संकट सब खो कर जाते हैं ||","खुला सभी हित प्रभु द्वार है, चमत्कार को नमस्कार है ||","अन्धा भी यदि ध्यान लगावे, उसके नेत्र शीघ्र खुल जावें ||","बहरा भी सुनने लग जावे, पगले का पागलपन जावे ||"]},{lines:["अखंड ज्योति का घृत जो लगावे, संकट उसका सब कट जावे ||","चरणों की रज अति सुखकारी, दुख दरिद्र सब नाशनहारी ||","चालीसा जो मन से ध्यावे, पुत्र पौत्र सब सम्पति पावे ||","पार करो दुखियों की नैया, स्वामी तुम बिन नहीं खिवैया ||"]},{lines:["प्रभु मैं तुम से कुछ नहिं चाहूं, दर्श तिहारा निश दिन पाऊँ ||","करुं वन्दना आपकी, श्रीचन्द्र प्रभु जिनराज |","जंगल में मंगल कियो, रखो 'सुरेश' की लाज ||"]}]},"dharmanath-chalisa":{id:"dharmanath-chalisa",category:"chalisa",title:"श्री धर्मनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["धर्मनाथ तीर्थेश को, वन्दूँ बारम्बार।"]},{lines:["धर्मध्यान को प्राप्त कर, हो जाऊँ भवपार॥"]},{lines:["धर्मनाथ भगवान का, चालीसा सुखकार।"]},{lines:["पढ़ो सभी भव्यात्मा, करो आत्म उद्धार॥"]},{lines:["धर्मनाथ भगवान हैं, धर्मचक्र के ईश।"]},{lines:["इनके चरण सरोज को, नमूँ नमाकर शीश॥"]},{lines:["धर्मध्वजा फहराई है, अखिल विश्व में नाथ!"]},{lines:["शत इन्द्रों से वंद्य प्रभू जी, असुरों द्वारा पूज्य प्रभू जी॥"]},{lines:["॥ चौपाई ॥"]},{lines:["उत्तम क्षमा आदि दस धर्मी। प्रगटे मूर्तिमान श्रीधर्म॥"]},{lines:["जग से हरण हरें सब अधर्म। शाश्वत सुख दें प्रभुवर धर्म॥"]},{lines:["नगर रत्नपुर के शासक थे। भूपति भानु प्रजापालक थे॥"]},{lines:["महादेवी सुव्रता अभिन्न। पुत्र – अभाव से रहतीं खिन्न॥"]},{lines:["'प्राचेतस' मुनि अवधिलीन। मात-पिता को धीरज दीन॥"]},{lines:['"पुत्र तुम्हारे हों क्षेमकर। जग में कहलायें तीर्थंकर॥']},{lines:["धीरज हुआ दम्पति-मन में। साधु-वचन हों सत्य जगत में॥"]},{lines:["'मोह' 'सुरम्य' विमान से तजकर। जननी उदर बसे प्रभु आकर॥"]},{lines:["तत्क्षण सब देवों के परिकर। गर्भकल्याणक करें खुश होकर॥"]},{lines:["तेरस माघ मास उजियारी। जन्मे तीन ज्ञान के धारी॥"]},{lines:["तीन भुवन द्युति छाई न्यारी। सब ही जीवों को सुखकारी॥"]},{lines:["माता को निद्रा में सुलाकर। लिया शची ने गोद में आकर॥"]},{lines:["मेरु पर अभिषेक कराया। 'धर्मनाथ' शुभ नाम धराया॥"]},{lines:["देख शिशु-सौन्दर्य अपार। किये इन्द्र ने नयन हजार॥"]},{lines:["बीता बचपन यौवन आया। अद्भुत आकर्षक तन पाया॥"]},{lines:["पिता ने तब युवराज बनाया। राज-काज उनको समझाया॥"]},{lines:["चित्र श्रृंगारवती का लेकर। दूत सभा में बैठा आकर॥"]},{lines:["स्वयंवर हेतु निमन्त्रण देकर। गया नाथ की स्वीकृति लेकर॥"]},{lines:["मित्र प्रभाकर को संग लेकर। कुण्डिनपुर को गए धर्म-वर॥"]},{lines:["शृंगारवती ने वरा प्रभु को। पुष्पक यान पे आए घर को॥"]},{lines:["मात-पिता करें हार्दिक प्यार। प्रजाजनों ने किया सत्कार॥"]},{lines:["सर्वप्रिय था उनका शासन। नीति सहित करते प्रजापालन॥"]},{lines:["उल्कापात देखकर एक दिन। भोग-विमुख हो गए श्री जिन॥"]},{lines:["सुत 'सुधर्म' को सौंपा राज। शिविका में प्रभु गए विराज॥"]},{lines:["चलते संग सहस नृपराज। गए शालवन में जिनराज॥"]},{lines:["शुक्ल त्रयोदशी माघ महीना। सन्ध्या समय मुनि पदवी गहीना॥"]},{lines:["दो दिन रहे ध्यान में लीना, दिव्य दीप्ति धरें वस्त्र विहीना。"]},{lines:["तीसरे दिन हेतु आहार। पाटलिपुत्र को हुआ विहार॥"]},{lines:["अन्तराय बत्तीस निखार। धन्यसेन नृप दें आहार॥"]},{lines:["मौन अवस्था रहती प्रभु की, कठिन तपस्या एक वर्ष की॥"]},{lines:["पूरणमासी पौष मास की, अनुभूति हुई दिव्याभास की॥"]},{lines:["चतुर्निकाय के सुरगण आये। उत्सव ज्ञानकल्याण मनाये॥"]},{lines:["समोशरण निर्माण करायें। अन्तरिक्ष में प्रभु पधराये॥"]},{lines:["निरक्षरी कल्याणी वाणी। कर्णपुटों से पीतें प्राणी॥"]},{lines:['"जीव जगत में जानो अनन्त। पुद्गल तो है अनन्तानन्त॥']},{lines:["धर्म-अधर्म और नभ एक। काल समेत द्रव्य षट् देख॥"]},{lines:["रागमुक्त हो जाने रूप। शिवसुख उसको मिले अनूप॥"]},{lines:["सुन कर बहुत हुए व्रतधारी। बहुतों ने जिन दीक्षाधारी॥"]},{lines:["आर्यखण्ड में हुआ विहार। भूमण्डल में धर्म प्रचार॥"]},{lines:["गढ़ सम्मेद गए आखिर में। लीन हुए निज अन्तरंग में॥"]},{lines:["शुक्लध्यान का हुआ प्रताप। हुए अघाति-घात निष्पाप॥"]},{lines:["नष्ट किए जग के सन्ताप। मुक्तिमहल में पहुँचे आप॥"]},{lines:["ज्येष्ठ चतुर्थी शुक्ल पक्षवर। पूजा करें सुर, कूट सुदत्तवर॥"]},{lines:["लक्षण 'वज्रदण्ड' शुभ जान। हुआ धर्म से धर्म का 'मान'॥"]},{lines:["जो प्रतिदिन प्रभु के गुण गाते। 'अरुणा' वे भी शिवसुख पाते॥"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री धर्मनाथाय नमः)"]}]},"kunthunath-chalisa":{id:"kunthunath-chalisa",category:"chalisa",title:"श्री कुन्थुनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["सिद्धप्रभू को नमन कर, सिद्ध करूँ सब काम।"]},{lines:["सत्रहवें तीर्थेश का, करना है गुणगान।।"]},{lines:["कुन्थुनाथ भगवान हैं, श्रीकांता के लाल।"]},{lines:["कामदेव हैं तेरवें, उनको करूँ प्रणाम।।"]},{lines:["श्रीजिनवाणी मात की, हो जावे शुभदृष्टि।"]},{lines:["तभी पूर्ण हो जाएगी, गुणगाथा संक्षिप्त।।"]},{lines:["॥ चौपाई ॥"]},{lines:["दयासिन्धु कुन्थु जिनराज, भवसिन्धु तिरने को जहाज।"]},{lines:["कामदेव-चक्री महाराज, दया करो हम पर भी आज।।"]},{lines:["जय श्री कुन्थुनाथ गुणखान, परम यशस्वी महिमावान।"]},{lines:["हस्तिनापुर नगरी के भूपति, शूरसेन कुरुवंशी अधिपति।।"]},{lines:["महारानी थी श्रीमति उनकी, वर्षा होती थी रतनन की。"]},{lines:["प्रतिपदा बैसाख उजियारी, जन्मे तीर्थंकर बलधारी।।"]},{lines:["गहन भक्ति अपने उर धारे, हस्तिनापुर आए सुर सारे。"]},{lines:["इन्द्र प्रभु को गोद में लेकर, गए सुमेरु हर्षित होकर।।"]},{lines:["न्हवन करें निर्मल जल लेकर, ताण्डव नृत्य करें भक्ति-भर。"]},{lines:["कुन्थुनाथ नाम शुभ देकर, इन्द्र करें स्तवन मनोहर।।"]},{lines:["दिव्य-वस्त्र-भूषण पहनाए, वापिस हस्तिनापुर को आए。"]},{lines:["क्रम-क्रम से बढे बालेन्दु सम, यौवन शोभा धारें हितकार।।"]},{lines:["धनु पैंतालीस उन्नत प्रभु-तन, उत्तम शोभा धारें अनुपम。"]},{lines:["आयु पिचानवे वर्ष हजार, लक्षण 'अज' धारें हितकार।।"]},{lines:["राज्याभिषेक हुआ विधिपूर्वक, शासन करें सुनीति पूर्वक。"]},{lines:["चक्ररतन शुभ प्राप्त हुआ जब, चक्रवर्ती कहलाए प्रभु तब।।"]},{lines:["एक दिन गए प्रभु उपवन में, शान्त मुनि इक देखें मग में。"]},{lines:["इगित किया तभी अंगुलिसे, “देखो मुनिको”- कहा मंत्री से।।"]},{lines:["मंत्री ने पूछा जब कारण, “किया मोक्षहित मुनिपद धारण”。"]},{lines:["कारण करें और स्पष्ट, “मुनिपद से ही कर्म हों नष्ट”।।"]},{lines:["मंत्री का तो हुआ बहाना, किया वस्तुत: निज कल्याणा。"]},{lines:["चित्त विरक्त हुआ विषयों से, तत्व चिन्तन करते भावों से।।"]},{lines:["निज सुत को सौंपा सब राज, गए सहेतुक वन जिनराज。"]},{lines:["पंचमुष्टि से केशलौंचकर, धार लिया पद नगन दिगम्बर।।"]},{lines:["तीन दिन बाद गए गजपुर को, धर्ममित्र पड़गाहें प्रभु को。"]},{lines:["मौन रहे सोलह वर्षों तक, सहे शीत-वर्षा और आतप।।"]},{lines:["स्थिर हुए तिलक तरु-जल में, मगन हुए निज ध्यान अटल में。"]},{lines:["आतम में बढ़ गई विशुद्धि, केवलज्ञान की हो गई सिद्धि।।"]},{lines:["सूर्यप्रभा सम सोहें आप्त, दिग्मण्डल शोभा हुई व्याप्त。"]},{lines:["समोशरण रचना सुखकार, ज्ञानतृषित बैठे नर – नार।।"]},{lines:["विषय – भोग महा विषमय है, मन को कर देते तन्मय हैं。"]},{lines:["विष से मरते एक जनम में, भोग विषाक्त मरे भव-भव में।।"]},{lines:["क्षण भंगुर मानव का जीवन, विद्युतवत् विनसे अगले क्षण。"]},{lines:["सान्ध्य ललिमा के सदृश्य ही, यौवन हो जाता अदृश्य ही।।"]},{lines:["जब तक आतम बुद्धि नही हो, तब तक दरश विशुद्धि नहीं हों。"]},{lines:["पहले विजित करो पंचेन्द्रिय, आतमबल से बनो जितेन्द्रिय।।"]},{lines:["भव्य भारती प्रभु की सुनकर, श्रावकजन आनन्दित को कर。"]},{lines:["श्रद्धा से व्रत धारण करते, शुभ भावों का अर्जन करते।।"]},{lines:["शुभायु एक मास रही जब, शैल सम्मेद पे वास किया तब。"]},{lines:["धारा प्रतिमा योग वहाँ पर, काटा कर्मबन्ध सब प्रभुवर।।"]},{lines:["मोक्षकल्याणक करते सुरगण, कट ज्ञानधर करते पूजन。"]},{lines:["चक्री-कामदेव-तीर्थंकर, कुन्थुनाथ थे परम हितंकर।।"]},{lines:["चालीसा जो पढ़े भाव से, स्वयंसिद्ध हों निज स्वभाव से。"]},{lines:["धर्म चक्र के लिए प्रभु ने, चक्र सुदर्शन तज डाला।।"]},{lines:["इसी भावना ने अरुणा को, किया ज्ञान में मतवाला。"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री कुन्थुनाथाय नमः)"]}]},"mahavir-chalisa":{id:"mahavir-chalisa",category:"chalisa",title:"श्री महावीर चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीश नवा अरिहन्त को, सिद्धन करूँ प्रणाम ।","उपाध्याय आचार्य का, ले सुखकारी नाम ॥","सर्व साधु और सरस्वती, जिन मन्दिर सुखकार ।","महावीर भगवान को, मन-मन्दिर में धार ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय महावीर दयालु स्वामी, वीर प्रभु तुम जग में नामी ।","वर्धमान है नाम तुम्हारा, लगे हृदय को प्यारा प्यारा ॥"]},{lines:["शांति छवि और मोहनी मूरत, शान हँसीली सोहनी सूरत ।","तुमने वेश दिगम्बर धारा, कर्म-शत्रु भी तुम से हारा ॥"]},{lines:["क्रोध मान अरु लोभ भगाया, महा-मोह तुमसे डर खाया ।","तू सर्वज्ञ सर्व का ज्ञाता, तुझको दुनिया से क्या नाता ॥"]},{lines:["तुझमें नहीं राग और द्वेष, वीर रण राग तू हितोपदेश ।","तेरा नाम जगत में सच्चा, जिसको जाने बच्चा बच्चा ॥"]},{lines:["भूत प्रेत तुम से भय खावें, व्यन्तर राक्षस सब भग जावें ।","महा व्याध मारी न सतावे, महा विकराल काल डर खावे ॥"]},{lines:["काला नाग होय फन धारी, या हो शेर भयंकर भारी ।","ना हो कोई बचाने वाला, स्वामी तुम्हीं करो प्रतिपाला ॥"]},{lines:["अग्नि दावानल सुलग रही हो, तेज हवा से भड़क रही हो ।","नाम तुम्हारा सब दुख खोवे, आग एकदम ठण्डी होवे ॥"]},{lines:["हिंसामय था भारत सारा, तब तुमने कीना निस्तारा ।","जनम लिया कुण्डलपुर नगरी, हुई सुखी तब प्रजा सगरी ॥"]},{lines:["सिद्धारथ जी पिता तुम्हारे, त्रिशला के आँखों के तारे ।","छोड़ सभी झंझट संसारी, स्वामी हुए बाल-ब्रह्मचारी ॥"]},{lines:["पंचम काल महा-दुखदाई, चाँदनपुर महिमा दिखलाई ।","टीले में अतिशय दिखलाया, एक गाय का दूध गिराया ॥"]},{lines:["सोच हुआ मन में ग्वाले के, पहुँचा एक फावड़ा लेके ।","सारा टीला खोद बगाया, तब तुमने दर्शन दिखलाया ॥"]},{lines:["जोधराज को दुख ने घेरा, उसने नाम जपा जब तेरा ।","ठंडा हुआ तोप का गोला, तब सब ने जयकारा बोला ॥"]},{lines:["मंत्री ने मन्दिर बनवाया, राजा ने भी द्रव्य लगाया ।","बड़ी धर्मशाला बनवाई, तुमको लाने को ठहराई ॥"]},{lines:["तुमने तोड़ी बीसों गाड़ी, पहिया खसका नहीं अगाड़ी ।","ग्वाले ने जो हाथ लगाया, फिर तो रथ चलता ही पाया ॥"]},{lines:["पहिले दिन बैशाख बदी के, रथ जाता है तीर नदी के ।","मीना गूजर सब ही आते, नाच-कूद सब चित उमगाते ॥"]},{lines:["स्वामी तुमने प्रेम निभाया, ग्वाले का बहु मान बढ़ाया ।","हाथ लगे ग्वाले का जब ही, स्वामी रथ चलता है तब ही ॥"]},{lines:["मेरी है टूटी सी नैया, तुम बिन कोई नहीं खिवैया ।","मुझ पर स्वामी जरा कृपा कर, मैं हूँ प्रभु तुम्हारा चाकर ॥"]},{lines:["तुम से मैं अरु कछु नहीं चाहूँ, जन्म-जन्म तेरे दर्शन पाऊँ ।","चालीसे को 'चन्द्र' बनावे, बीर प्रभु को शीश नवावे ॥"]},{lines:["॥ सोरठा ॥"]},{lines:["नित चालीसहिं बार, पाठ करे चालीस दिन ।","खेय सुगन्ध अपार, वर्धमान के सामने ॥","होय कुबेर समान, जन्म दरिद्री होय जो ।","जिसके नहिं संतान, नाम वंश जग में चले ॥"]}]},"mallinath-chalisa":{id:"mallinath-chalisa",category:"chalisa",title:"श्री मल्लिनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["मल्लिनाथ महाराज का, चालीसा मनहार।"]},{lines:["चालीस दिन तुम नियम से, पढ़िये चालीस बार॥"]},{lines:["दर्शन को चलते समय, करिये इसका पाठ।"]},{lines:["दुःख-चिन्ता, बाधा मिटे, उपजै 'सुमत' विचार॥"]},{lines:["॥ चौपाई ॥"]},{lines:["मोहमल्ल मद-मर्दन करते, मन्मथ दुर्द्धर का मद हरते॥"]},{lines:["धैर्य खड्ग से कर्म निवारे, बालयति को नमन हमारे॥"]},{lines:["बिहार प्रान्त में मिथिला नगरी, राज्य करें कुम्भ काश्यप गोत्री॥"]},{lines:["प्रभावती महारानी उनकी, वर्षा होती थी रत्नों की॥"]},{lines:["अपराजित विमान को तजकर, जननी उदर बसे प्रभु आकर॥"]},{lines:["मंगसिर शुक्ल एकादशी शुभ दिन, जन्मे तीन ज्ञान युत श्री जिन॥"]},{lines:["पूनम चन्द्र समान हों शोभित, इन्द्र न्हवन करते हो मोहित॥"]},{lines:["ताण्डव नृत्य करें खुश होकर, निरखें प्रभुको विस्मित होकर॥"]},{lines:["बढ़े प्यार से मल्लि कुमार, तन की शोभा हुई अपार॥"]},{lines:["पचपन सहस आयु प्रभुवर की, पच्चीस धनु अवगाहन वपु की॥"]},{lines:["देख पुत्र की योग्य अवस्था, पिता ब्याह की करें व्यवस्था॥"]},{lines:["मिथिलापुरी को खूब सजाया, कन्या पक्ष सुन कर हर्षाया॥"]},{lines:["निज मन में करते प्रभु मन्थन, है विवाह एक मीठा बन्धन॥"]},{lines:["विषय भोग रुपी ये कर्दम, आत्मज्ञान को करदे दुर्गम॥"]},{lines:["नहीं आसक्त हुए विषयन में, हुए विरक्त गए प्रभु वन में॥"]},{lines:["मंगसिर शुक्ल एकादशी पावन, स्वामी दीक्षा करते धारण॥"]},{lines:["दो दिन का धरा उपवास, वन में ही फिर किया निवास॥"]},{lines:["तीसरे दिन प्रभु करें विहार, नन्दिषेण नृप दें आहार॥"]},{lines:["पात्रदान से हर्षित होकर, अचरज पाँच करें सुर आकर॥"]},{lines:["मल्लिनाथ जी लौटे वन में, लीन हुए आतम चिन्तन में॥"]},{lines:["आत्मशुद्धि का प्रबल प्रमाण, अल्प समय में उपजा ज्ञान॥"]},{lines:["केवलज्ञानी हुए छः दिन में, घण्टे बजने लगे स्वर्ग में॥"]},{lines:["समोशरण की रचना साजे, अन्तरिक्ष में प्रभु विराजे॥"]},{lines:["विशाक्ष आदि अट्ठाइस गणधर, चालीस सहस थे ज्ञानी मुनिवर॥"]},{lines:["पथिकों को सत्पथ दिखलाया, शिवपुर का सन्मार्ग बताया॥"]},{lines:["औषधि-शास्त्र-अभय-आहार, दान बताए चार प्रकार॥"]},{lines:["पंच समिति और लब्धि पाँच, पाँचों पैताले हैं साँच॥"]},{lines:["षट् लेश्या जीव षट्काय, षट् द्रव्य कहते समझाय॥"]},{lines:["सात तत्त्व का वर्णन करते, सात नरक सुन भविमन डरते॥"]},{lines:["सातों नय को मन में धारें, उत्तम जन सन्देह निवारें॥"]},{lines:["दीर्घ काल तक दिए उपदेश, वाणी में कटुता नहीं लेश॥"]},{lines:["आयु रहने पर एक मास, शिखर सम्मेद पे करते वास॥"]},{lines:["योग निरोध का करते पालन, प्रतिमा योग करें प्रभु धारण॥"]},{lines:["कर्म नष्ट कीने जिनराई, तत्क्षण मुक्ति-रमा परणाई॥"]},{lines:["फाल्गुन शुक्ल पंचमी न्यारी, सिद्ध हुए जिनवर अविकारी॥"]},{lines:["मोक्ष कल्याणक सुर-नर करते, संवल कूट की पूजा करते॥"]},{lines:["चिन्ह 'कलश' था मल्लिनाथ का, जीन महापावन था उन का॥","नरपुंगव थे वे जिनश्रेष्ठ, स्त्री कहें जो सत्य न लेश॥"]},{lines:["कोटि उपाय करो तुम सोच, स्त्रीभव से हो नहीं मोक्ष॥"]},{lines:["महाबली थे वे शूरवीर, आत्म शत्रु जीते धर-धीर॥"]},{lines:["अनुक्म्पा से प्रभु मल्लि की, अल्पायु हो भव-वल्लि की॥"]},{lines:["अरज यही है बस हम सब की, दृष्टि रहे सब पर करुणा की॥"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री मल्लिनाथाय नमः)"]}]},"munisuvratnath-chalisa":{id:"munisuvratnath-chalisa",category:"chalisa",title:"श्री मुनिसुव्रतनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["पंचनमस्कृति मंत्र है, सर्व सुखों की खान।","पंचपदों युत मंत्र को, वंदूँ शीश नवाय।।","पंचपरमगुरु को नमूँ, पंचमगति मिल जाए।","रोग-शोक बाधा टलें, सुख अनन्त मिल जाए।।","श्रीमुनिसुव्रतनाथ का, यह चालीसा पाठ।","पढ़ लेवें जो भव्यजन, शनिग्रह होवें शांत।।","शारद माता तुम मुझे, दे दो आशिर्वाद।","तभी पूर्ण हो पाएगा, यह जिनवर गुणगान।।"]},{lines:["॥ चौपाई ॥"]},{lines:["अरिहंत सिद्ध आचार्य को करुं प्रणाम।","उपाध्याय सर्वसाधू करते स्वपर कल्याण।।","जिनधर्म, जिनागम, जिनमंदिर पवित्र धाम।","वीतराग की प्रतिमा को कोटि-कोटि प्रणाम।।"]},{lines:["जय मुनिसुव्रत दया के सागर, नाम प्रभु का लोक उजागर।।","सुमित्रा राजा के तुम नन्दा, मां शामा की आंखो के चन्दा।।","श्यामवर्ण मूरत प्रभू की प्यारी, गुणगान करें निशदिन नर नारी।।","मुनिसुव्रत जिन हो अन्तरयामी, श्रद्धा भाव सहित तुम्हें प्रणामी।।"]},{lines:["भक्ति आपकी जो निशदिन करता, पाप ताप भय संकट-हरता।।","प्रभू ; संकटमोचन नाम तुम्हारा, दीन दुखी जीवों का सहारा।।","कोई दरिद्री या तन का रोगी, प्रभू दर्शन से होते हैं निरोगी।।","मिथ्या तिमिर भयो अति भारी, भव भव की बाधा हरो हमारी।।"]},{lines:["यह संसार महा दुख दाई, सुख नहीं यहां दुख की खाई।।","मोह जाल में फंसा है बंदा, काटो प्रभु भव भव का फंदा।।","रोग शोक भय व्याधि मिटावो, भव सागर से पार लगावो।।","घिरा कर्म से चौरासी भटका, मोह माया बन्धन में अटका।।"]},{lines:["संयोग-वियोग भव भव का नाता, राग द्वेष जग में भटकाता।।","हित मित प्रित प्रभू की वाणी, स्वपर कल्याण करें मुनि ध्यानी।।","भव सागर बीच नाव हमारी, प्रभु पार करो यह विरद तिहारी।।","मन विवेक मेरा अब जागा, प्रभु दर्शन से कर्ममल भागा।।"]},{lines:["नाम आपका जपे जो भाई, लोका लोक सुख सम्पदा पाई।।","कृपा दृष्टी जब आपकी होवे, धन आरोग्य सुख समृधि पावे।।","प्रभु चरणन में जो जो आवे, श्रद्धा भक्ति फल वांच्छित पावे।।","प्रभु आपका चमत्कार है न्यारा, संकट मोचन प्रभु नाम तुम्हारा।।"]},{lines:["सर्वज्ञ अनंत चतुष्टय के धारी, मन वच तन वंदना हमारी।।","सम्मेद शिखर से मोक्ष सिधारे, उद्धार करो मैं शरण तिहांरे।।","महाराष्ट्र का पैठण तीर्थ, सुप्रसिद्ध यह अतिशय क्षेत्र।।","मनोज्ञ मन्दिर बना है भारी, वीतराग की प्रतिमा सुखकारी।।"]},{lines:["चतुर्थ कालीन मूर्ति है निराली, मुनिसुव्रत प्रभू की छवि है प्यारी।।","मानस्तंभ उत्तग की शोभा न्यारी, देखत गलत मान कषाय भारी।।","मुनिसुव्रत शनिग्रह अधिष्ठाता, दुख संकट हरे देवे सुख साता।।","शनि अमावस की महिमा भारी, दूर-दूर से आते नर नारी।।","मुनिसुव्रत दर्शन महा हितकारी, मन वच तन वंदना हमारी।।"]},{lines:["॥ सोरठा ॥"]},{lines:["सम्यक् श्रद्धा से चालीसा, चालीस दिन पढिये नर-नार।","मुक्ति पथ के राही बन, भक्ति से होवे भव पार।।"]},{lines:["Related Sadhana"]},{lines:["📿"]},{lines:["Bhaktamar Stotra","Powerful devotional hymn"]},{lines:["🕉️"]},{lines:["Namokar Chalisa","Universal prayer"]}]},"naminath-chalisa":{id:"naminath-chalisa",category:"chalisa",title:"श्री नमिनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["सतत पूज्यनीय भगवान, नमिनाथ जिन महिभावान॥"]},{lines:["भक्त करें जो मन में ध्याय, पा जाते मुक्ति-वरदान॥"]},{lines:["जय श्री नमिनाथ जिन स्वामी।"]},{lines:["वसु गुण मण्डित प्रभु प्रणमामि॥"]},{lines:["मिथिला नगरी प्रान्त बिहार।"]},{lines:["श्री विजय राज्य करें हितकार॥"]},{lines:["विप्रा देवी महारानी थीं।"]},{lines:["रूप गुणों की वे खानि थीं॥"]},{lines:["कृष्णाश्विन द्वितीया सुखदाता।"]},{lines:["षोडश स्वप्न देखती माता॥"]},{lines:["॥ चौपाई ॥"]},{lines:["अपराजित विमान को तजकर।"]},{lines:["जननी उदर बसे प्रभु आकर॥"]},{lines:["कृष्ण असाढ़- दशमी सुखकार।"]},{lines:["भूतल पर हुआ प्रभु-अवतार॥"]},{lines:["आयु सहस दस वर्ष प्रभु की।"]},{lines:["धनु पन्द्रह अवगाहना उनकी॥"]},{lines:["तरुण हुए जब राजकुमार।"]},{lines:["हुआ विवाह तब आनन्दकार॥"]},{lines:["एक दिन भ्रमण करें उपवन में।"]},{lines:["वर्षा ऋतु में हर्षित मन में॥"]},{lines:["नमस्कार करके दो देव।"]},{lines:["कारण कहने लगे स्वयमेव॥"]},{lines:["ज्ञात हुआ है क्षेत्र विदेह में।"]},{lines:["“भावी तीर्थंकर तुम जग में॥"]},{lines:["देवों से सुन कर ये बात।"]},{lines:["राजमहल लौटे नमिनाथ॥"]},{lines:["सोच हुआ भव- भव में भ्रमण का।"]},{lines:["चिन्तन करते रहे मोचन का॥"]},{lines:["परम दिगम्बर व्रत करूँ अर्जन।"]},{lines:["रतनत्रयधन करूँ उपार्जन॥"]},{lines:["सप्रभ सुत को राज सौंपकर।"]},{lines:["गए चित्रवन में श्रीजिनवर॥"]},{lines:["दशमी असाढ़ मास की कारी।"]},{lines:["सहस नृपति संग दीक्षाधारी॥"]},{lines:["दो दिन का उपवास धारकर।"]},{lines:["आतम लीन हुए श्री प्रभुवर॥"]},{lines:["तीसरे दिन जब किया विहार।"]},{lines:["भूप वीरपुर दें आहार॥"]},{lines:["नौ वर्षों तक तप किया वन में।"]},{lines:["एक दिन मौलि श्री तरु तल में॥"]},{lines:["अनुभूति हुई दिव्याभास।"]},{lines:["शुक्ल एकादशी मंगसिर मास॥"]},{lines:["नमिनाथ हुए ज्ञान के सागर।"]},{lines:["ज्ञानोत्सव करते सुर आकर॥"]},{lines:["समोशरण था सभा विभूषित।"]},{lines:["मानस्तम्भ थे चार सुशोभित॥"]},{lines:["हुआ मौनभंग दिव्य ध्वनि से।"]},{lines:["सब दुख दूर हुए अवनि से॥"]},{lines:["आत्म पदार्थ से सत्ता सिद्ध।"]},{lines:["करता तन में 'अहम्' प्रसिद्ध॥"]},{lines:["बाह्येन्द्रियों में करण के द्वारा।"]},{lines:["अनुभव से कर्ता स्वीकारा॥"]},{lines:["पर-परिणति से ही यह जीव।"]},{lines:["चतुर्गति में भ्रमे सदीव॥"]},{lines:["रहे नरक-सागर पर्यन्त।"]},{lines:["सहें भूख – प्यास तिर्यन्च॥"]},{lines:["हुआ मनुज तो भी संक्लेश।"]},{lines:["देवों में भी ईर्ष्या – द्वेष॥"]},{lines:["नहीं सुखों का कहीं ठिकाना।"]},{lines:["सच्चा सुख तो मोक्ष में माना॥"]},{lines:["मोक्ष गति का द्वार है एक।"]},{lines:["नरभव से ही पायें नेक॥"]},{lines:["सुन कर मगन हुए सब सुरगण।"]},{lines:["व्रत धारण करते श्रावक जन॥"]},{lines:["हुआ विहार जहाँ भी प्रभु का।"]},{lines:["हुआ वहीं कल्याण सभी का॥"]},{lines:["करते रहे विहार जिनेश।"]},{lines:["एक मास रही आयु शेष॥"]},{lines:["शिखर सम्मेद के ऊपर जाकर।"]},{lines:["प्रतिमा योग धरा हर्षा कर॥"]},{lines:["शुक्ल ध्यान की अग्नि प्रजारी।"]},{lines:["हने अघाति कर्म दुखकारी॥"]},{lines:["अजर-अमर- शाश्वत पद पाया।"]},{lines:["सुर-नर सबका मन हर्षाया॥"]},{lines:["शुभ निर्वाण महोत्सव करते।"]},{lines:["कूट मित्रधर पूजन करते॥"]},{lines:["प्रभु हैं नीलकमल से अलंकृत।"]},{lines:["हम हों उत्तम फल से उपकृत॥"]},{lines:["नमिनाथ स्वामी जगवन्दन।"]},{lines:["'अरुणा' करती प्रभु-अभिवन्दन॥"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री नमिनाथाय नमः)"]}]},"namokar-chalisa":{id:"namokar-chalisa",category:"chalisa",title:"णमोकार महामंत्र चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["वंदूँ श्रीअरिहंत पद, सिद्ध नाम सुखकार।","सूरी पाठक साधुगण, हैं जग के आधार ।।१।।","इन पाँचों परमेष्ठि से, सहित मूल यह मंत्र।","अपराजित व अनादि है, णमोकार शुभ मंत्र ।।२।।","णमोकार महामंत्र को, नमन करूँ शतबार।","चालीसा पढ़कर लहूँ, स्वात्मधाम साकार ।।३।।"]},{lines:["॥ चौपाई ॥"]},{lines:["हो जैवन्त अनादिमंत्रम्, णमोकार अपराजित मंत्रम् ।।१।।","पंच पदों से युक्त सुयंत्रम्, सर्वमनोरथ सिद्धि सुतंत्रम् ।।२।।","पैंतिस अक्षर माने इसमें, अट्ठावन मात्राएँ भी हैं ।।३।।","अतिशयकारी मंत्र जगत में, सब मंगल में कहा प्रथम है ।।४।।"]},{lines:["जिसने इसका ध्यान लगाया, मनमन्दिर में इसे बिठाया ।।५।।","उसका बेड़ा पार हो गया, भवदधि से उद्धार हो गया ।।६।।","अंजन बना निरंजन क्षण में, शूली बदली सिंहासन में ।।७।।","नाग बना फूलों की माला, हो गई शीतल अग्नी ज्वाला ।।८।।"]},{lines:["जीवन्धर से इसी मंत्र को, सुना श्वान ने मरणासन्न हो ।।९।।","शांतभाव से काया तजकर, पाया पद यक्षेन्द्र हुआ तब ।।१०।।","एक बैल ने मंत्र सुना था, राजघराने में जन्मा था ।।११।।","जातिस्मरण हुआ जब उसको, उसने खोजा उपकारी को ।।१२।।"]},{lines:["पद्मरुची को गले लगाया, आगे मैत्री भाव निभाया ।।१३।।","कालान्तर में वही पद्मरुचि, राम बने तब बहुत धर्मरुचि ।।१४।।","बैल बना सुग्रीव बन्धुवर! दोनों के सम्बन्ध मित्रवर ।।१५।।","रामायण की सत्य कथा है, णमोकार से मिटी व्यथा है ।।१६।।"]},{lines:["ऐसी ही कितनी घटनाएँ, नए पुराने ग्रन्थ बताएँ ।।१७।।","इस जग में इस मंत्र की महिमा, कही सभी ने इसकी गरिमा ।।१८।।","हो अपवित्र पवित्र दशा में, सदा करें संस्मरण हृदय में ।।१९।।","जपें शुद्धतन से जो माला, वे पाते हैं सौख्य निराला ।।२०।।"]},{lines:["अन्तर्मन पावन होता है, बाहर का अघमल धोता है ।।२१।।","णमोकार के पैंतिस व्रत हैं, श्रावक करते श्रद्धायुत हैं ।।२२।।","हर घर के दरवाजे पर तुम, महामंत्र को लिखो जैनगण ।।२३।।","जैनी संस्कृति दर्शाएगा, सुख समृद्धि भी दिलवाएगा ।।२४।।"]},{lines:["एक तराजू के पलड़े पर, सारे गुण भी रख देने पर ।।२५।।","दूजा पलड़ा मंत्र सहित जो, उठा न पाए कोई उसको ।।२६।।","उठते चलते सभी क्षणों में, जंगल पर्वत या महलों में ।।२७।।","महामंत्र को कभी न छोड़ो, सदा इसी से नाता जोड़ो ।।२८।।"]},{lines:["देखो! इक सुभौम चक्री था, उसने मन में इसे जपा था ।।२९।।","देव मार नहिं पाया उसको, तब छल युक्ति बताई नृप को ।।३०।।","उसके चंगुल में फस करके, लिखा मंत्र राजा ने जल में ।।३१।।","ज्यों ही उस पर कदम रख दिया, देव की शक्ती प्रगट कर दिया ।।३२।।"]},{lines:["देव ने उसको मार गिराया, नरक धरा को नृप ने पाया ।।३३।।","मंत्र का यह अपमान कथानक, सचमुच ही है हृदय विदारक ।।३४।।","भावों से भी न अविनय करना, सदा मंत्र पर श्रद्धा करना ।।३५।।","इसके लेखन में भी फल है, हाथ नेत्र हो जाएं सफल है ।।३६।।"]},{lines:["णमोकार की बैंक खुली है, ज्ञानमती प्रेरणा मिली है ।।३७।।","जम्बूद्वीप-हस्तिनापुर में, मंत्रों का व्यापक संग्रह है ।।३८।।","इसकी किरण प्रभा से जग में, फैले सुख शांती जन-जन में ।।३९।।","मन-वच-तन से इसे नमन है, महामंत्र का करूं स्मरण मैं ।।४०।।"]}]},"neminath-chalisa":{id:"neminath-chalisa",category:"chalisa",title:"श्री नेमिनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["नेमिनाथ भगवान ने, लिया जहाँ अवतार।"]},{lines:["उस शौरीपुर तीर्थ को, वन्दन बारम्बार।।"]},{lines:["पुन: प्रभू जी ने जहाँ, पाया पद निर्वाण।"]},{lines:["सिद्धक्षेत्र गिरनार को, नमन करूँ शत बार।।"]},{lines:["बाइसवें तीर्थेश के, चालीसा का पाठ।"]},{lines:["पढ़ने से हो जाएगा, तुमको भी वैराग।।"]},{lines:["विद्यादेवी को नमूँ, वो ही देंगी ज्ञान।"]},{lines:["बिना ज्ञान वैâसे करूँ, नेमिनाथ गुणगान।।"]},{lines:["॥ चौपाई ॥"]},{lines:["श्री जिनवाणी शीश धार कर, सिद्ध प्रभु का करके ध्यान।"]},{lines:["लिखूं नेमि-चालीसा सुखकार, नेमिप्रभु की शरण में आन॥"]},{lines:["समुन्द्र विजय यादव कुलराई, शौरीपुर रजधानी कहाई।"]},{lines:["शिवादेवी उनकी महारानी, षष्ठी कार्तिक शुक्ल बखानी॥"]},{lines:["सुख से शयन करें शय्या पर, सपने देखे सोलह सुन्दर।"]},{lines:["तज विमान जयंत अवतारे, हुए मनोरथ पूरण सारे॥"]},{lines:["प्रतिदिन महल में रतन बरसते, यदुवंशी निज मन में हरषते।"]},{lines:["दिन षष्ठी श्रावण शुक्ला का, हुआ अभ्युदय पुत्र रतन का॥"]},{lines:["तीन लोक में आनंद छाया, प्रभु को मेरु पर पधराश।"]},{lines:["न्हवन हेतु जल ले क्षीरसागर, मणियों के थे कलश मनोहर॥"]},{lines:["कर अभिषेक किया परणाम, अरिष्ट नेमि दिया शुभ नाम।"]},{lines:["शोभित तुमसे सत्य मराल, जीता तुमने काल कराल॥"]},{lines:["सहस अष्ट लक्षण सुललाम, नीलकमल सम वर्ण अभिराम।"]},{lines:["वज्र शरीर दस धनुष उतंग, लज्जित तुम छवि देव अनंग॥"]},{lines:["चाचा – ताऊ रहते साथ, नेमि- कृष्ण चचेरे भ्रात।"]},{lines:["धरा जब यौवन जिनराई, राजुल के संग हुई सगाई॥"]},{lines:["जूनागढ़ को चली बरात, छप्पन कोटि यादव साथ।"]},{lines:["सुना वहाँ पशुओं का क्रन्दन, तोड़ा मोर – मुकुट और कंगन॥"]},{lines:["बाड़ा खोल दिया पशुओं का, धारा वेष दिगम्बर मुनि का।"]},{lines:["कितना अद्भुत संयम मन में, ज्ञानीजन अनुभव करें मन में॥"]},{lines:["नौ-नौ आँसू राजुल रोवे, बारम्बार मूर्छित होवे।"]},{lines:["फेंक दिया दुल्हन श्रृंगार, रो-रो कर यों करे पुकार॥"]},{lines:["नौ भव की तोड़ी क्यों प्रीत, कैसी है ये धर्म की रीत।"]},{lines:["नेमि दें उपदेश त्याग का, उमड़ा सागर वैराग्य का॥"]},{lines:["राजुल ने भी ले ली दीक्षा, हुई संयम उत्तीर्ण परीक्षा।"]},{lines:["दो दिन रहकर के निराहार, तीसरे दिन करें स्वामी विहार॥"]},{lines:["वरदत्त महीपति दें आहार, पंचाश्चर्य हुए सुखकार।"]},{lines:["रहे मौन से छप्पन दिन तक, तपते रहे कठिनतम तप व्रत॥"]},{lines:["प्रतिपदा आश्विन उजियारी, हुए केवली प्रभु अविकारी।"]},{lines:["समोशरण की रचना करते, सुरगण ज्ञान की पूजा करते॥"]},{lines:["भवि जीवों के पुण्य प्रभाव से, दिव्य ध्वनि खिरती सद्भाव से।"]},{lines:["जो भी होता है आत्मज्ञ, वो ही होता है सर्वज्ञ॥"]},{lines:["ज्ञानी निज आतम को निहारे, अज्ञानी पर्याय संवारे।"]},{lines:["है अद्भुत वैरागी दृष्टि, स्वाश्रित हो तजते सब सृष्टि॥"]},{lines:["जैन धर्म तो धर्म सभी का, है निजधर्म ये प्राणीमात्र का।"]},{lines:["जो भी पहचाने जिनदेव, वो ही जाने आतम देव॥"]},{lines:["रागादि के उन्मूलन को, पूजें सब जिनदेवचरण को।"]},{lines:["देश-विदेश में हुआ विहार, गए अन्त में गढ़ गिरनार॥"]},{lines:["सब कर्मों का करके नाश, प्रभु ने पाया पद अविनाश।"]},{lines:["जो भी प्रभु की शरण में आते, उनको मन वांछित मिलजाते॥"]},{lines:["ज्ञानार्जन करके शास्त्रों से, लोकार्पण करती श्रद्धा से।"]},{lines:["'अरुणा'बस ये ही वर चाहे, निज आतम दर्शन हो जाए॥"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री नेमिनाथाय नमः)"]}]},"padmaprabhu-chalisa":{id:"padmaprabhu-chalisa",category:"chalisa",title:"श्री पद्मप्रभु चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीश नवा अरिहंत को, सिद्धन करू प्रणाम।","उपाध्याय आचार्य का, ले गुणकारी नाम॥","सर्व साधू और सरस्वती, जिनमन्दिर सुखकार।","पदमपुरी के पद्म को, मन मंदिर में धार॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री पद्मप्रभु गुणकारी, भाविजनो को तुम हो हितकारी।","देवों के तुम देव कहाओ, छट्टे तीर्थंकर कहलाओ॥"]},{lines:["तुम जग में सर्वज्ञ कहाओ, छट्ठे तीर्थंकर कहलाओ।","तीन काल तिहुँ जग को जानो, सब बातों को क्षण में पहचानो॥"]},{lines:["वेष दिगंबर धारण हारे, तुमसे कर्म शत्रु भी हारे।","मूर्ति तुम्हारी कितनी सुन्दर, दृष्टि सुखद जमती नासा पर॥"]},{lines:["क्रोध मान मद लोभ भगाया, राग द्वेष का लेश ना पाया।","वीतराग तुम कहलाते हो, सब जग के मन को भाते हो॥"]},{lines:["कौशाम्बी नगरी कहलाए, राजा धारण जी बतलाए।","सुन्दरी नाम सुसीमा उनके, जिनके उर से स्वामी जन्मे॥"]},{lines:["कितनी लम्बी उमर कहाई, तीस लाख पूरब बतलाई।","इक दिन हाथी बंधा निरख कर, झट आया वैराग्य उमड़कर॥"]},{lines:["कार्तिक सुदी त्रयोदशी भारी, तुमने मुनि पद दीक्षा धारी।","सारे राज पाट को तज कर, तभी मनोहर वन में पहुँचे॥"]},{lines:["तप कर केवल ज्ञान उपाया, चैत्र सुदी पूनम कहलाया।","एक सौ दस गणधर बतलाए, मुख्य वज्र चामर कहलाए॥"]},{lines:["लाखों मुनि आर्जिका लाखों, श्रावक और श्राविका लाखों।","असंख्यात तिर्यंच बताए, देवी देव गिनत नहीं पाए॥"]},{lines:["फिर सम्मेद शिखर पर जाकर, शिवरमणी को ली परणाकर।","पंचम काल महादुखदायी, जब तुमने महिमा दिखलाई॥"]},{lines:["जयपुर राज ग्राम बाड़ा है, स्टेशन शिवदासपुरा है।","मूळा नाम का जाट का लड़का, घर की नीव खोदने लगा॥"]},{lines:["खोदत खोदत मूर्ति दिखाई, उसने जनता को दिखलाई।","चिन्ह कमल लख लोग लुगाई, पदम प्रभु की मूर्ति बताई॥"]},{lines:["मन में अति हर्षित होते हैं, अपने मन का मल धोते हैं।","तुमने यह अतिशय दिखलाया, भूत प्रेत को दूर भगाया॥"]},{lines:["जब गंधोदक छींटे मारें, भूत प्रेत तब आप बकारे।","जपने से जप नाम तुम्हारा, भूत प्रेत वो करे किनारा॥"]},{lines:["ऐसी महिमा बतलाते हैं, अंधे भी आँखे पाते हैं।","प्रतिमा श्वेत वर्ण कहलाए, देखत ही हृदय को भाए॥"]},{lines:["ध्यान तुम्हारा जो धरता है, इस भव से वो नर तरता है।","अंधा देखे गूंगा गावे, लंगड़ा पर्वत पर चढ़ जावे॥"]},{lines:["बहरा सुन सुन खुश होवे, जिस पर कृपा तुम्हारी होवे।","मैं हूँ स्वामी दास तुम्हारा, मेरी नैया कर दो पारा॥"]},{lines:["चालीसे को 'चन्द्र' बनाए, पद्मप्रभु को शीश नवाए॥"]},{lines:["॥ सोरठा ॥"]},{lines:["नित ही चालीस बार, पाठ करे चालीस दिन।","खेय सुगंध अपार, पदमपुरी में आय के॥","होय कुबेर समान, जन्म दरिद्र होय जो।","जिसके नहीं संतान, नाम वंश जग में चले॥"]}]},"parshvanath-chalisa":{id:"parshvanath-chalisa",category:"chalisa",title:"श्री पार्श्वनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","उपाध्याय आचार्य का ले, सुखकारी नाम॥","सर्व साधु और सरस्वती, जिन मंदिर सुखकार।","अहिच्छत्र और पार्श्व को, मन मंदिर में धार॥"]},{lines:["॥ चौपाई ॥"]},{lines:["पार्श्वनाथ जगत हितकारी, हो स्वामी तुम व्रत के धारी।","सुर नर असुर करें तुम सेवा, तुम ही सब देवन के देवा॥"]},{lines:["तुमसे करम शत्रु भी हारा, तुम कीना जग का निस्तारा।","अश्वसेन के राजदुलारे, वामा की आँखों के तारे॥"]},{lines:["काशी जी के स्वामी कहाये, सारी परजा मौज उड़ाए।","इक दिन सब मित्रों को लेके, सैर करन को वन में पहुँचे॥"]},{lines:["हाथी पर कसकर अम्बारी, इक जंगल में गई सवारी।","एक तपस्वी देख वहाँ पर, उससे बोले वचन सुनाकर॥"]},{lines:["तपसी! तुम क्यों पाप कमाते, इस लक्कड़ में जीव जलाते।","तपसी तभी कुदाल उठाया, उस लक्कड़ को चीर गिराया॥"]},{lines:["निकले नाग-नागनी कारे, मरने के थे निकट बिचारे।","रहम प्रभु के दिल में आया, तभी मंत्र नवकार सुनाया॥"]},{lines:["मरकर वो पाताल सिधाए, पद्मावती धरणेन्द्र कहाए।","तपसी मरकर देव कहाया, नाम कमठ ग्रंथों में गाया॥"]},{lines:["एक समय श्री पारस स्वामी, राज छोड़कर वन की ठानी।","तप करते थे ध्यान लगाए, इक दिन कमठ वहाँ पर आए॥"]},{lines:["फौरन ही प्रभु को पहिचाना, बदला लेना दिल में ठाना।","बहुत अधिक बारिश बरसाई, बादल गरजे बिजली गिराई॥"]},{lines:["बहुत अधिक पत्थर बरसाए, स्वामी तन को नहीं हिलाए।","पद्मावती धरणेन्द्र भी आए, प्रभु की सेवा में चित लाए॥"]},{lines:["धरणेन्द्र ने फन फैलाया, प्रभु के सिर पर छत्र बनाया।","पद्मावती ने फन फैलाया, उस पर स्वामी को बैठाया॥"]},{lines:["कर्मनाश प्रभु ज्ञान उपाया, समोशरण देवेन्द्र रचाया।","यही जगह अहिच्छत्र कहाए, पात्र केशरी जहाँ पर आए॥"]},{lines:["शिष्य पाँच सौ संग विद्वाना, जिनको जाने सकल जहाना।","पार्श्वनाथ का दर्शन पाया, सबने जैन धरम अपनाया॥"]},{lines:["अहिच्छत्र श्री सुन्दर नगरी, जहाँ सुखी थी परजा सगरी।","राजा श्री वसुपाल कहाए, वो इक जिन मंदिर बनवाए॥"]},{lines:["प्रतिमा पर पालिश करवाया, फौरन इक मिस्त्री बुलवाया।","वह मिस्तरी मांस था खाता, इससे पालिश था गिर जाता॥"]},{lines:["मुनि ने उसे उपाय बताया, पारस दर्शन व्रत दिलवाया।","मिस्त्री ने व्रत पालन कीना, फौरन ही रंग चढ़ा नवीना॥"]},{lines:["गदर सतावन का किस्सा है, इक माली का यों लिक्खा है।","वह माली प्रतिमा को लेकर, झट छुप गया कुँए के अन्दर॥"]},{lines:["उस पानी का अतिशय भारी, दूर होय सारी बीमारी।","जो अहिच्छत्र हृदय से ध्यावे, सो नर उत्तम पदवी पावे॥"]},{lines:["पुत्र संपदा की बढ़ती हो, पापों की इकदम घटती हो।","है तहसील आँवला भारी, स्टेशन पर मिले सवारी॥"]},{lines:["रामनगर इक ग्राम बराबर, जिसको जाने सब नारी-नर।","चालीसे को 'चन्द्र' बनाए, हाथ जोड़कर शीश नवाए॥"]},{lines:["॥ सोरठा ॥"]},{lines:["नित चालीसहिं बार, पाठ करे चालीस दिन।","खेय सुगंध अपार, अहिच्छत्र में आय के॥","होय कुबेर समान, जन्म दरिद्री होय जो।","जिसके नहिं संतान, नाम वंश जग में चले॥"]},{lines:["Related Sadhana"]},{lines:["🪔"]},{lines:["Parshvanath Puja","Complete worship ritual"]},{lines:["🐍"]},{lines:["Uvasaggaharam","Removes obstacles"]}]},"pushpadanta-chalisa":{id:"pushpadanta-chalisa",category:"chalisa",title:"श्री पुष्पदन्त चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ श्री पुष्पदन्त चालीसा ॥"]},{lines:["दुख से तप्त मरुस्थल भव में, सघन वृक्ष सम छायाकार।"]},{lines:["पुष्पदन्त पद-छत्र-छाँव में, हम आश्रय पावें सुखकार॥"]},{lines:["जम्बूद्वीप के भरत क्षेत्र में, काकन्दी नामक नगरी में।"]},{lines:["राज्य करें सुग्रीव बलधारी, जयरामा रानी थी प्यारी॥"]},{lines:["नवमी फाल्गुन कृष्ण बखानी, षोडश स्वप्न देखती रानी।"]},{lines:["सुत तीर्थंकर गर्भ में आएं, गर्भ कल्याणक देव मनायें॥"]},{lines:["प्रतिपदा मंगसिर उजियारी, जन्मे पुष्पदन्त हितकारी।"]},{lines:["जन्मोत्सव की शोभा न्यारी, स्वर्गपुरी सम नगरी प्यारी॥"]},{lines:["आयु थी दो लक्ष पूर्व की, ऊँचाई शत एक धनुष की।"]},{lines:["थामी जब राज्य बागडोर, क्षेत्र वृद्धि हुई चहुँ ओर॥"]},{lines:["इच्छाएँ उनकी सीमित, मित्र प्रभु के हुए असीमित।"]},{lines:["एक दिन उल्कापात देखकर, दृष्टिपात किया जीवन पर॥"]},{lines:["स्थिर कोई पदार्थ ना जग में, मिले ना सुख किंचित् भवमग में।"]},{lines:["ब्रह्मलोक से सुरगण आए, जिनवर का वैराग्य बढ़ाएं॥"]},{lines:["सुमति पुत्र को देकर राज, शिविका में प्रभु गए विराज।"]},{lines:["पुष्पक वन में गए हितकार, दीक्षा ली संग भूप हज़ार॥"]},{lines:["गए शैलपुर दो दिन बाद, हुआ आहार वहाँ निराबाध।"]},{lines:["पात्रदान से हर्षित होकर, पंचाश्चर्य करे सुर आकर॥"]},{lines:["प्रभुवर लौट गए उपवन को, तत्पर हुए कर्म-छेदन को।"]},{lines:["लगी समाधि नाग वृक्ष तल, केवलज्ञान उपाया निर्मल॥"]},{lines:["इन्द्राज्ञा से समोशरण की, धनपति ने आकर रचना की।"]},{lines:["दिव्य देशना होती प्रभु की, ज्ञान पिपासा मिटी जगत की॥"]},{lines:["अनुपेक्षा द्वादश समझाई, धर्म स्वरूप विचारो भाई।"]},{lines:["शुक्ल ध्यान की महिमा गाई, शुक्ल ध्यान से हों शिवराई॥"]},{lines:["चारों भेद सहित धारो मन, मोक्षमहल में पहुँचो तत्क्षण।"]},{lines:["मोक्ष मार्ग दर्शाया प्रभु ने, हर्षित हुए सकल जन मन में॥"]},{lines:["इन्द्र करें प्रार्थना जोड़ कर, सुखद विहार हुआ श्री जिनवर।"]},{lines:["गए अन्त में शिखर सम्मेद, ध्यान में लीन हुए निरखेद॥"]},{lines:["शुक्ल ध्यान से किया कर्मक्षय, सन्ध्या समय पाया पद आक्षय।"]},{lines:["अश्विन अष्टमी शुक्ल महान, मोक्ष कल्याणक करें सुर आन॥"]},{lines:["सुप्रभ कूट की करते पूजा, सुविधि नाथ नाम है दूजा।"]},{lines:["मगरमच्छ है लक्षण प्रभु का, मंगलमय जीवन था उनका॥"]},{lines:["शिखर सम्मेद में भारी अतिशय, प्रभु प्रतिमा है चमत्कारमय।"]},{lines:["कलियुग में भी आते देव, प्रतिदिन नृत्य करें स्वयमेव॥"]},{lines:["घुंघरू की झंकार गूंजती, सब के मन को मोहित करती।"]},{lines:["ध्वनि सुनी हमने कानो से, पूजा की बहु उपमानो से॥"]},{lines:["हमको है ये दृढ श्रद्धान, भक्ति से पायें शिवथान।"]},{lines:["भक्ति में शक्ति है न्यारी, राह दिखायें करुणाधारी॥"]},{lines:["पुष्पदन्त गुणगान से, निश्चित हो कल्याण।"]},{lines:["हम सब अनुक्रम से मिले, अन्तिम पद निर्वाण॥"]}]},"sambhavnath-chalisa":{id:"sambhavnath-chalisa",category:"chalisa",title:"श्री संभवनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["श्री संभव जिनराज का, करने से गुणगान।"]},{lines:["कोई असंभव कार्य भी, संभव हो तत्काल।।"]},{lines:["चालीसा का पाठ मैं, लिखना चाहूँ आज।"]},{lines:["वागीश्वरि देवी सरस्वती देवी मुझे, दे दो आर्शीवाद।।"]},{lines:["॥ चौपाई ॥"]},{lines:["संभव जिन की भक्ती कर लो, भववारिधि से तिरना हो तो।।"]},{lines:["नगरी श्रावस्ती अति प्यारी, मात सुषेणा वहाँ की रानी।।"]},{lines:["पुण्यशालि पितु दृढ़रथ राजा, जिनका नरभव सफल हुआ था।।"]},{lines:["संभव जिनवर ग्रैवेयक तज, आए मात गरभ में जिस दिन।।"]},{lines:["वह दिन फाल्गुन सुदि अष्टमी का, शुभ मंगलमय पावन क्षण था।।"]},{lines:["कार्तिक पूर्णिमा में प्रभु जन्मे, कीर्ति सुरभि व्यापी तिहुँ जग में।।"]},{lines:["सोलह सौ कर तनु ऊँचाई, साठ लाख पूरब थी आयू।।"]},{lines:["जन्मत ही दश अतिशय प्रगटे, प्रभु को सुर-विद्याधर नमते।।"]},{lines:["राजा बनकर धर्मनीति से, राज्य किया बहु कुशल रीति से।।"]},{lines:["इक दिन मेघों का विभ्रम लख, प्रभु ने छोड़ दिया वैभव सब।।"]},{lines:["दीक्षा के शुभ भाव हो गए, आत्मज्ञान से पूर्ण हो गए।।"]},{lines:["तजा परिग्रह केश लौंच कर, ध्यान धरा पूरब को मुख कर।"]},{lines:["धारण कर उस दिन उपवास, वन में ही फिर किया निवास।"]},{lines:["आत्मशुद्धि का प्रबल प्रमाण, तत्क्षण हुआ मनः पर्याय ज्ञान।"]},{lines:["प्रथमाहार हुआ मुनिवर का, धन्य हुआ जीवन ‘सुरेन्द्र’ का।"]},{lines:["पंचाश्चर्यो से देवों के, हुए प्रजाजन सुखी नगर के।"]},{lines:["चौदह वर्ष की आत्म-सिद्धि, स्वयं ही उपजी केवल ऋद्धि।"]},{lines:["कृष्ण चतुर्थी कार्तिक सार, समोशरण रचना हितकार।"]},{lines:["खिरती सुखकारी जिनवाणी, निज भाषा में समझे प्राणी।"]},{lines:["“विषयभोग हैं विषसम विषमय, इनमे मत होना तुम तन्मय।"]},{lines:["तृष्णा बढ़ती है भोगों से, काया घिरती है रोगों से।"]},{lines:["जिनलिंग से निज को पहचानो, अपना शुद्धातम सरधानो।"]},{lines:["दर्शन ज्ञान चरित्र बतावे, मोक्ष मार्ग एकत्व दिखाये।"]},{lines:["जीवों का सन्मार्ग बताया, भव्यो का उद्धार कराया।"]},{lines:["गणधर एक सौ पाँच प्रभु के, मुनिवर पन्द्रह सहस संघ के।"]},{lines:["देवी-देव-मनुज बहुतेरे, सभा में थे तिर्यंच घनेरे।"]},{lines:["एक महीना उम्र रही जब, पहुँच गए सम्मेद शिखर तब।"]},{lines:["अचल हुए खड़गासन में प्रभु, कर्म नाश कर हुए स्वयम्भु।"]},{lines:["चैत सुदी षष्ठी थी न्यारी, धवल कूट की महिमा भारी।"]},{lines:["साठ लाख पूर्व का जीवन, पग में अश्व का था शुभ लक्षण।"]},{lines:["चालीसा श्री संभवनाथ, पाठ करो श्रद्धा के साथ।"]},{lines:["मनवांछित सब पूरण होवे, ‘अरुणा’ जनम-मरण दुख खोवे।"]},{lines:["॥ शंभु छंद ॥"]},{lines:["यह संभव प्रभु का चालीसा, पढ़ लेना तुम चालीस दिन तक।"]},{lines:["इक-दो बार नहीं भव्यों! चालीस बार पढ़ना प्रतिदिन।।"]},{lines:["इसको पढ़ने से कार्य-असंभव भी, संभव हो जाएगा।"]},{lines:["संभव जिनवर का वंदन भी, बेड़ा पार लगाएगा।।"]}]},"shantinath-chalisa":{id:"shantinath-chalisa",category:"chalisa",title:"श्री शान्तिनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","उपाध्याय आचार्य का ले, सुखकारी नाम॥","सर्व साधु और सरस्वती, जिन मंदिर सुखकार।","शान्तिनाथ भगवान को, मन मंदिर में धार॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री शान्तिनाथ जिन स्वामी, तीन लोक के तुम हो स्वामी।","सोलाहवें तीर्थंकर हारी, महिमा गावे सब नर नारी॥","तुमने शांति जगत में फैलाई, सब जीवों की पीर मिटाई।","हस्तिनापुर में जनम लियो है, माता ऐरा देवी को सुख दियो है॥"]},{lines:["पिता विश्वसेन के राजदुलारे, प्रजा के तुम प्राण पियारे।","कामदेव के तुम अवतारी, सुन्दर सोहे मूरत थारी॥","चक्रवर्ती तुम पदवी पाई, चौदह रत्न नवनिधि आई।","लेकिन तुमको मोह न आया, वैराग्य का रंग चढ़ आया॥"]},{lines:["राज-पाट सब तजकर स्वामी, वन में जाके हुए वैरागी।","घोर तपस्या तुमने कीनी, कर्मन की सब शक्ति छीनी॥","केवल ज्ञान प्रकाश भयो है, लोकालोक झलाक रह्यो है।","समवशरण में देह विराजे, सुर-नर मुनि सब वंदन साजे॥"]},{lines:["धर्म का तुमने पंथ बताया, मोक्ष मार्ग सबको दिखलाया।","सत्य अहिंसा का व्रत लीना, पापों का तुम नाश कीना॥","मृग लांछन प्रभु चरण सोहे, दर्शन कर मन सबका मोहे।","जो भी तुम्हारे दर पे आवे, मनवांछित फल सो नर पावे॥"]},{lines:["सम्मेद शिखर से मोक्ष पधारे, सुर-नर सब जयकार पुकारे।","हम सब हैं प्रभु शरण तिहारी, काटो सब संकट अविकारी (हमारी)।","शान्तिनाथ की जो चालीसा गावे, सुख-संपत्ति वो घर में पावे।","रोग-शोक सब दूर नसावे, 'चन्द्र' प्रभु के गुण गावे॥"]},{lines:["॥ सोरठा ॥"]},{lines:["नित चालीसहिं बार, पाठ करे चालीस दिन।","खेय सुगंध अपार, श्री शान्तिनाथ के सामने॥","होय कुबेर समान, जन्म दरिद्री होय जो।","जिसके नहिं संतान, नाम वंश जग में चले॥"]}]},"sheetalnath-chalisa":{id:"sheetalnath-chalisa",category:"chalisa",title:"श्री शीतलनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीतलनाथ भगवान को, वन्दूँ बारम्बार।"]},{lines:["शीतल जिन के जाप से, होवे बेड़ा पार।।"]},{lines:["भद्रिलपुर के भूपति, दृढ़रथ पितु-विख्यात।"]},{lines:["नन्दा सुनन्दा मात थी, जग में अति विख्यात।।"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री शीतलनाथ स्वामी, तीन लोक के अन्तरयामी।"]},{lines:["दसवें तीर्थंकर कहलाए, कल्पवृक्ष का चिह्न धराए।"]},{lines:["प्रभु का वरण सुवर्ण कहाया, नब्बे धनुष मान काया।"]},{lines:["पूरब लाख एक थी आयु, वज्रवृषभ संहनन बतायु।"]},{lines:["माघ बदी द्वादशी को जाई, केवल ज्ञान सम्पदा पाई।"]},{lines:["समोशरण रचना रचवाई, भव्य जीवों को राह दिखाई।"]},{lines:["अश्विन सुदी अष्टमी भारी, मोक्ष गए प्रभु मंगलकारी।"]},{lines:["सम्मेद शिखर से शिवपुर सिधारे, सुर-नर मुनि सब जय-जयकारे।"]},{lines:["जो कोई प्रभु का ध्यान लगावे, मनवांछित फल सो नर पावे।"]},{lines:["रोग-दोष सब दूर नसावे, घर में सुख-सम्पत्ति आवे।"]},{lines:["शीतल जिन का पाठ जो, करे नित्य चित्त लाय।"]},{lines:["'चन्द्र' कहे कर जोड़ के, शिवपुर में बस जाय।।"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री शीतलनाथाय नमः)"]}]},"shreyansnath-chalisa":{id:"shreyansnath-chalisa",category:"chalisa",title:"श्री श्रेयांसनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["श्रेयांसनाथ भगवान को, नाऊँ निशदिन शीश।"]},{lines:["काटो सकल क्लेश मम, तुम ही हो जगदीश।।"]},{lines:["सिंहपुर नगरी भली, विष्णुराज भूपाल।"]},{lines:["वेणुदेवी मात थी, उपजे दीनदयाल।।"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री श्रेयांसनाथ गुणखान, तुम हो ग्यारहवें भगवान।"]},{lines:["गैंडा चिह्न चरण के माहीं, लखत ही पाप रहे कछु नाहीं।"]},{lines:["अस्सी धनुष मान तन सोहे, कनक वरण लख मन मोहे।"]},{lines:["चौरासी लाख वर्ष की आयु, पूर्ण करन मोक्ष सिधायु।"]},{lines:["फाल्गुन कृष्ण त्रयोदशी भाई, दीक्षा ले वन खण्ड जो जाई।"]},{lines:["माघ बदी अमावस भारी, केवलज्ञान हुआ हितकारी।"]},{lines:["धर्मोपदेश दिया तुम भारी, भव्य जीवों की विपदा टारी।"]},{lines:["श्रावण शुक्ला पूरणमासी, मोक्ष गए तुम अविनाशी।"]},{lines:["जो जन तुमको नित प्रति ध्यावे, जनम-मरण के फन्द नसावे।"]},{lines:["रोग-शोक नहिं आवे नेरे, रहे सर्वदा सुख घनेरे।"]},{lines:["श्रेयांसनाथ के चरण में, नमन करूँ शत बार।"]},{lines:["दास जान अपना प्रभु, कर दीजे भव पार।।"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री श्रेयांसनाथाय नमः)"]}]},"sumatinath-chalisa":{id:"sumatinath-chalisa",category:"chalisa",title:"श्री सुमतिनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["सुमतिनाथ जिनराज को, नमूँ जोरि कर हाथ।"]},{lines:["सुमति दीजिए आप स्रु, तुम ही त्रिभुवन नाथ।।"]},{lines:["अयोध्या नगरी भली, मेघरथ नृप विख्यात।"]},{lines:["मंगला रानी मात थी, उपजे त्रिभुवन तात।।"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री सुमतिनाथ भगवान, पाँचवें तुम तीर्थंकर जान।"]},{lines:["चकवा चिह्न चरण के माहीं, लखत ही पाप रहे कछु नाहीं।"]},{lines:["तप्त सुवर्ण वरण तन सोहे, तीन सौ धनुष मान मन मोहे।"]},{lines:["चालीस लाख पूर्व की आयु, भोग निराले मोक्ष सिधायु।"]},{lines:["वैशाख सुदी नवमी को भाई, तप कल्याणक महिमा गाई।"]},{lines:["चैत्र सुदी एकादशी जानो, केवलज्ञान हुआ परमानो।"]},{lines:["धर्म तीर्थ का प्रवर्तन कीना, भव्य जीवों को तारन कीना।"]},{lines:["चैत्र सुदी एकादशी आई, मोक्ष गए प्रभु मंगलदाई।"]},{lines:["जो जन तुमको निशदिन ध्यावे, वो नर निश्चय शिवपुर जावे।"]},{lines:["संकट-विघ्न सभी टल जावे, घर में सुख-सम्पत्ति आवे।"]},{lines:["सुमतिनाथ के चरण में, जो नित नावे शीश।"]},{lines:["'चन्द्र' कहे कर जोड़ के, तुम ही हो जगदीश।।"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री सुमतिनाथाय नमः)"]}]},"suparshvanath-chalisa":{id:"suparshvanath-chalisa",category:"chalisa",title:"श्री सुपार्श्वनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["सुपार्श्वनाथ जिनराज को, वन्दूँ शीश नवाय।"]},{lines:["जिन सुमिरन से होत है, सब पातक नश जाय।।"]},{lines:["वाराणसी नगरी भली, सुप्रतिष्ठ महाराज।"]},{lines:["पृथिवी देवी मात थीं, सफल भयो सब काज।।"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री सुपार्श्वनाथ जन-प्यारे, सातवें तीर्थंकर कहलाए।"]},{lines:["स्वास्तिक चिह्न चरण में सोहे, लखत ही सुर-नर मन को मोहे।"]},{lines:["हरित वरण तन शोभा भारी, दो सौ धनुष मान अविकारी।"]},{lines:["बीस लाख पूर्व की आयु, भोग सकल सुख मोक्ष सिधायु।"]},{lines:["ज्येष्ठ सुदी द्वादशी को भाई, दीक्षा ले प्रभु वन को जाई।"]},{lines:["फाल्गुन कृष्ण षष्ठी को जानो, केवलज्ञान हुआ परमानो।"]},{lines:["धर्म देशना प्रभु की हुई, भव्य जीवों की मति सुधि भई।"]},{lines:["फाल्गुन कृष्ण सप्तमी आई, मोक्ष पधारे जिनवराई।"]},{lines:["जो जन तुमको नित प्रति ध्यावे, आधि-व्याधि सब दूर नसावे।"]},{lines:["पुत्र-पौत्र सुख-सम्पत्ति पावे, अन्त समय शिवपुर को जावे।"]},{lines:["सुपार्श्वनाथ के चरण में, नमन करूँ बारम्बार।"]},{lines:["दास जान अपना प्रभु, कर दीजे भव पार।।"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री सुपार्श्वनाथाय नमः)"]}]},"vasupujya-chalisa":{id:"vasupujya-chalisa",category:"chalisa",title:"श्री वासुपूज्य चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["वासुपूज्य जिनराज को, वन्दूँ शीश नवाय।"]},{lines:["जिन सुमिरन से होत है, सब पातक नश जाय।।"]},{lines:["चम्पापुर नगरी भली, वासुपूज्य महाराज।"]},{lines:["जयावती रानी मात थीं, सफल भयो सब काज।।"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री वासुपूज्य जिनराई, बारहवें तीर्थंकर भाई।"]},{lines:["महिष चिह्न चरण में सोहे, लखत ही सुर-नर मन को मोहे।"]},{lines:["रक्त वरण तन शोभा भारी, सत्तर धनुष मान अविकारी।"]},{lines:["बहत्तर लाख वर्ष की आयु, भोग सकल सुख मोक्ष सिधायु।"]},{lines:["फाल्गुन बदी अमावस भाई, दीक्षा ले प्रभु वन को जाई।"]},{lines:["माघ सुदी दूज को जानो, केवलज्ञान हुआ परमानो।"]},{lines:["धर्म देशना प्रभु की हुई, भव्य जीवों की मति सुधि भई।"]},{lines:["आषाढ़ सुदी चौदस आई, मोक्ष पधारे जिनवराई।"]},{lines:["जो जन तुमको नित प्रति ध्यावे, आधि-व्याधि सब दूर नसावे।"]},{lines:["पुत्र-पौत्र सुख-सम्पत्ति पावे, अन्त समय शिवपुर को जावे।"]},{lines:["वासुपूज्य के चरण में, नमन करूँ बारम्बार।"]},{lines:["दास जान अपना प्रभु, कर दीजे भव पार।।"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री वासुपूज्य जिनेन्द्राय नमः)"]}]},"vimalnath-chalisa":{id:"vimalnath-chalisa",category:"chalisa",title:"श्री विमलनाथ चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["विमलनाथ भगवान की, महिमा है अपरम्पार।"]},{lines:["चालीसा के पाठ से, होवे बेड़ा पार।।"]},{lines:["कांपिल्य नगरी विषै, कृतवर्मा भूपाल।"]},{lines:["माता जयश्यामा तने, उपजे दीनदयाल।।"]},{lines:["॥ चौपाई ॥"]},{lines:["जय श्री विमलनाथ जिनराई, महिमा तीन लोक में छाई।।"]},{lines:["साठ लाख वर्ष की आयु, समचतुरस्त्र मूरत सुखदायी।।"]},{lines:["षट् हजार धनु काया धारी, वराह वाहन के असवारी।।"]},{lines:["स्वर्ण वरण तन सोहें प्यारा, निरावरण सब जग को निहारा।।"]},{lines:["सुक्ल ध्यान धर कर्म नसाए, केवल ज्ञान प्रकाश कराए।।"]},{lines:["सम्मेद शिखर तें मोक्ष पधारे, सुर नर मुनि सब वंदन धारे।।"]},{lines:["जो कोई तुमको मन से ध्यावे, रिद्धि-सिद्धि सुख संपत्ति पावे।।"]},{lines:["संकट कटें मिटें सब बाधा, पूरण होवे मन की साध।।"]},{lines:["पुत्र हीन को पुत्र हो जावे, निर्धन भी धन-दौलत पावे।।"]},{lines:["रोग-शोक नहिं आवे पास, पूरण होवे सबकी आस।।"]},{lines:["मैं हूँ प्रभु! दास तुम्हारा, कर दीजे भव से निस्तारा।।"]},{lines:["'चन्द्र' प्रभु के गुण गावे, भक्ति भाव से शीश नवावे।।"]},{lines:["(जाप: ॐ ह्रीं अर्हं श्री विमलनाथाय नमः)"]}]},"simandhar-chalisa":{id:"simandhar-chalisa",category:"chalisa",title:"श्री सीमंधर स्वामी चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥","विदेह क्षेत्र के नाथ हो, सीमंधर भगवान।","विचरमान जिनवर नमो, दीजे आतम ज्ञान॥","पुण्डरीकिणी नगरी भली, जन्म लियो जग त्राण।","श्रेयांस मात के लाड़ले, नमो नमो गुणवान॥"]},{lines:["॥ चौपाई ॥","जय सीमंधर देव दयाला, विदेह क्षेत्र के प्रभु गोपाला॥ १॥","वर्तमान जिनवर कहलाते, समवसरण में शोभा पाते॥ २॥","कोटि-कोटि मुनि संग बिराजे, दिव्यध्वनी गूंजे सुख साजे॥ ३॥","गंधकुटी पर प्रभु आसीना, कर्म-कालिमा सब हर लीना॥ ४॥","चौरासी गणधर सुखदाई, प्रभु वाणी जग में फैलाई॥ ५॥","आठों कर्म किए चकनाचूर, केवलज्ञान भयो भरपूर॥ ६॥","धनुष पांच सौ काया सोहे, लख सुर-नर का मानस मोहे॥ ७॥","स्वर्ण वर्ण देही अति प्यारी, नमो नमो जग तारणहारी॥ ८॥","जो कोई सीमंधर गुण गावे, उसके सब संताप नसावे॥ ९॥","मन मंदिर में ध्यान लगावे, सम्यग्दर्शन शीघ्रहि पावे॥ १०॥","विदेह क्षेत्र महिमा अति भारी, जहाँ विराजे प्रभु अविकारी॥ ११॥","भरत क्षेत्र से वन्दन करते, प्रभु चरणों में शीश धरते॥ १२॥","काम क्रोध मद लोभ विडारे, जनम-जनम के पाप निवारे॥ १३॥","अहिंसा का पाठ पढ़ाया, जीव दया का पंथ सिखाया॥ १४॥","जो नित चालीस दिन ध्यावे, भव-भव के सब संकट जावे॥ १५॥","रोग शोक सब दूर नसावे, सुख-शांति वैभव पद पावे॥ १६॥","अष्टद्रव्य से पूजा कीजे, आरती भाव सहित कर लीजे॥ १७॥","सीमंधर प्रभु अंतर्यामी, हम सेवक तुम हो जग स्वामी॥ १८॥","चालीस चौपाई जो गावे, निश्चय वह शिव मंदिर पावे॥ १९॥","अक्षय सुख का भोगी होवे, भवसागर के बंधन खोवे॥ २०॥"]},{lines:["॥ दोहा ॥","विदेह बिहारी नाथ तुम, सुनो हमारी टेर।","भव-भव के संकट हरो, करो न प्रभुवर देर॥","(जाप: ॐ ह्रीं अर्हं श्री सीमंधर स्वामिने नमः)"]}]},"jinendra-chalisa":{id:"jinendra-chalisa",category:"chalisa",title:"श्री जिनेन्द्र चालीसा",subtitle:"४० पद्य स्तुति एवं भक्ति पाठ",type:"structured",verses:[{lines:["॥ दोहा ॥","शीश नवा अरिहन्त को, सिद्धन करूँ प्रणाम।","उपाध्याय आचार्य का, ले सुखकारी नाम॥","सर्व साधु और सरस्वती, जिनवाणी सुखकार।","जिनेन्द्र प्रभु की भक्ति का, गाऊँ मंगलाचार॥"]},{lines:["॥ चौपाई ॥","जय जिनवर त्रिभुवन के स्वामी, अंतरयामी सुख के धामी॥ १॥","तीन लोक में महिमा भारी, भव-भय भंजन मंगलकारी॥ २॥","ऋषभदेव से वीर जिनेशा, चौबीसों जिन हरें कलेशा॥ ३॥","गर्भ जन्म तप केवल ज्ञाना, मोक्ष पधारे प्रभु कल्याणा॥ ४॥","समवसरण प्रभु अति सुखदायी, दिव्यध्वनी अमृत बरसाई॥ ५॥","अहिंसा का सन्देश सुनाया, जन-जन को जिनधर्म सिखाया॥ ६॥","क्रोध मान माया मद त्यागो, आत्म ज्ञान के पथ पर जागो॥ ७॥","जीव मात्र पर करुणा धारो, निज आतम का रूप निहारो॥ ८॥","राग-द्वेष के बंधन तोड़े, निज स्वभाव से नाता जोड़े॥ ९॥","अष्ट कर्म का नाश कराया, परम दिगम्बर वेश सजाया॥ १०॥","अरिहंत पद पाए सुखकारी, सिद्ध शिला बिराजे अविकारी॥ ११॥","आचार्य संघ का ध्यान धरें, मुनिजन संयम पालन करें॥ १२॥","उपाध्याय गुरु ज्ञान सिखावें, साधु मोक्ष का पंथ बतावें॥ १३॥","पंच परमेष्ठी पावन नाम, जपो निरंतर आठों याम॥ १४॥","जो जिनवर का ध्यान लगावे, मनवांछित फल निश्चय पावे॥ १५॥","दुःख दरिद्र सब दूर नसावे, सुख शांति आनंद बढ़ावे॥ १६॥","भक्ति भाव से जो गुण गावे, भव-भव के पातक कट जावे॥ १७॥","रत्नत्रय का मार्ग मिलावे, सम्यग्दर्शन ज्ञान जगावे॥ १८॥","सत्य अहिंसा व्रत अपनाओ, शील सदाचार मन लाओ॥ १९॥","अपरिग्रह अचौर्य सुखदाई, जिनवाणी माँ की बलिहारी॥ २०॥","प्रातः उठ जो चालीसा गावे, सब संकट से मुक्ति पावे॥ २१॥","विद्या बुद्धि विनय विशाला, होवे जनम-मरण उजियाला॥ २२॥","घर-आँगन में मंगल छावे, रिद्धि-सिद्धि नित बढ़ती जावे॥ २३॥","जिनवर कृपा रहे अनुदिन, कटे पाप सब छिन ही छिन॥ २४॥","नित जिन मंदिर दर्शन कीजे, पावन जिन अभिषेक करीजे॥ २५॥","पूजन अष्टद्रव्य सज ल्यावे, प्रभु चरणों में शीश नवावे॥ २६॥","शांतिधारा का फल पावे, सर्व व्याधि तत्काल नसावे॥ २७॥","जो भविजन यह पाठ करे, भवसागर से पार तरे॥ २८॥","चालीस दिन नित नियम से, पाठ करे जो कोय॥ २९॥","मनवांछित सब कार्य सिद्ध, विघ्न न कोई होय॥ ३०॥"]},{lines:["॥ दोहा ॥","जिनवाणी माता नमो, दूर करो अज्ञान।","पाऊँ मोक्ष महान सुख, दीजे केवलज्ञान॥","(जाप: ॐ ह्रीं श्री जिनेन्द्राय नमः)"]}]},"adinath-chalisa-chandkhedi":{id:"adinath-chalisa-chandkhedi",category:"chalisa",title:"श्री आदिनाथ चालीसा (चांदखेड़ी)",subtitle:"अतिशय क्षेत्र चाँदखेड़ी प्रथम तीर्थंकर आदिनाथ चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["चाँदखेड़ी अतिशय भलो, आदिनाथ जिनराज।","दर्शन पावत ही सरें, भक्तन के सब काज ॥","कोटा प्रान्त सुहावना, खानपुर के पास।","आदिनाथ स्वामी करें, संकट सब का नाश ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय जय आदिनाथ सुखदाई, चाँदखेड़ी में प्रभुता छाई ॥ १ ॥","श्यामवर्ण मूरत मन भावे, कोटि भानु की छटा लजावे ॥ २ ॥","नाभिराज मरुदेवी नंदन, कोटि-कोटि सुर करते वंदन ॥ ३ ॥","प्रथम तीर्थंकर प्रथम जिनेशा, काटो प्रभु जी सकल कलेशा ॥ ४ ॥"]},{lines:["भूमिगर्भ से प्रगटे स्वामी, तीन भुवन के अंतरयामी ॥ ५ ॥","संवत सत्रह सौ इकतीस मंझार, प्रगटे आदिनाथ करतार ॥ ६ ॥","किशनदास व्यापारी ध्यायो, स्वप्न देख अतिशय प्रगटायो ॥ ७ ॥","खोदी भूमि पाषाण हटायो, दिव्य रूप जिनवर का पायो ॥ ८ ॥"]},{lines:["रथ में मूरत बैठाई जब, रथ न हिले विस्मित जन सब ॥ ९ ॥","भूपति ने तब विनय पुकारी, यहीं विराजो प्रभु अविकारी ॥ १० ॥","मंदिर भव्य बन्यो सुखकारी, गूंजे जय जयकार तुम्हारी ॥ ११ ॥","जो जन चाँदखेड़ी आवे, मनवांछित सब वैभव पावे ॥ १२ ॥"]},{lines:["अंधे नयन मिले सुख पावें, कोढ़ी काया कंचन पावें ॥ १३ ॥","निर्धन धनवान बने सुखदायी, बांझिन सुत पावे हरषाई ॥ १४ ॥","भूत पिशाच निकट नहिं आवे, आदिनाथ जब नाम सुनावें ॥ १५ ॥","व्याधि उपाधि रोग नशावें, संकट मोचन नाम कहावें ॥ १६ ॥"]},{lines:["अमृत कुण्ड नीर सुखदाई, चरणामृत सब पीवें भाई ॥ १७ ॥","पंचामृत अभिषेक करावें, अष्टद्रव्य से अर्घ चढ़ावें ॥ १८ ॥","दीपमालिका ज्योति जगावें, भक्ति भाव से शीश नवावें ॥ १९ ॥","ऋषभदेव प्रभु करुणा कीजे, भव-सागर से तारन दीजे ॥ २० ॥"]},{lines:["इन्द्र चन्द्र नित सेवा आवें, सुर-नर मुनिवर महिमा गावें ॥ २१ ॥","सकल कषाय मिटावन हारे, आत्म-धर्म जगावन हारे ॥ २२ ॥","काम-क्रोध मद-लोभ विनाशी, वीतराग आनंद अविनाशी ॥ २३ ॥","समवशरण की शोभा भारी, द्वादश सभा बैठे अविकारी ॥ २४ ॥"]},{lines:["दिव्यध्वनी से संशय तोड़ा, जिनशासन से जग को जोड़ा ॥ २५ ॥","भरत-बाहुबली सुत सुखदाई, ब्राह्मी-सुन्दरी विद्या पाई ॥ २६ ॥","अहिंसा परम धर्म सिखलाया, जग को मुक्ति-पंथ दिखाया ॥ २७ ॥","चाँदखेड़ी तीरथ अति पावन, दर्शन से निर्मल हो पावन ॥ २८ ॥"]},{lines:["दूर-दूर से यात्री आवें, पूजा कर आनंद बढ़ावें ॥ २९ ॥","ध्वजा पताका मंदिर सोहे, शिखर देख मन सबका मोहे ॥ ३० ॥","घंटा घड़ियाल नगाड़े बाजे, आरती में जयकारा गाजे ॥ ३१ ॥","जो नर पाठ करे चालीस, पावे पद निर्भय अवनिपति ॥ ३२ ॥"]},{lines:["चालीसा चालीस दिन गावे, निश्चय भवसागर तिर जावे ॥ ३३ ॥","पुत्र-पौत्र सुख संपति बाढ़े, विघ्न भागें सब दुःख भागे ॥ ३४ ॥","मैं मूरख अज्ञान अपारा, प्रभु बिन कौन करे निस्तारा ॥ ३५ ॥","अपनी शरण में मुझको लीजे, भव-भव की यह बाधा छीजे ॥ ३६ ॥"]},{lines:["निसिदिन ध्यान धरूँ प्रभु तेरा, मेटो जनम मरण का फेरा ॥ ३७ ॥","विद्या बुद्धि विमल सुख दीजे, आतम रस में मगन करीजे ॥ ३८ ॥","आदिनाथ प्रभु अंतरयामी, तुम हो मेरे पूरण स्वामी ॥ ३९ ॥","चाँदखेड़ी की जय जयकार, आदिनाथ प्रभु बेड़ा पार ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["चाँदखेड़ी आदिनाथ का, जो ध्यावे दिन-रैन।","सकल अमंगल दूर हों, पावे शाश्वत चैन ॥","हाथ जोड़ विनती करूँ, सुनिये आदि जिनेश।","जिनवाणी सेवा करूँ, हरो सकल क्लेश ॥"]}]},"parshvanath-chalisa-ahichchhatra":{id:"parshvanath-chalisa-ahichchhatra",category:"chalisa",title:"श्री पार्श्वनाथ चालीसा (अहिच्छत्र)",subtitle:"तपस्थली अहिच्छत्र पार्श्वनाथ ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["अहिच्छत्र पावन मही, तप-कल्याणक धाम।","पार्श्वनाथ प्रभु को नमन, कोटि-कोटि परनाम ॥","कमठ-उपसर्ग निवार के, प्रगट्यो केवलज्ञान।","धरणेन्द्र-पद्मावती सेवे, पूजें सकल जहान ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय जय पार्श्वनाथ सुखदाता, भक्त जनों के भाग्य विधाता ॥ १ ॥","अश्वसेन वामा के नंदन, काशीपति त्रिभुवन के वंदन ॥ २ ॥","नील वर्ण तनु अतिशय सोहे, सर्प चिन्ह लख मानस मोहे ॥ ३ ॥","वैराग्य उमग्यो अंतर्यामी, वन में ध्यान लगायो स्वामी ॥ ४ ॥"]},{lines:["अहिच्छत्र वन पावन भारी, प्रभु तपस्या कीन्ह अपारी ॥ ५ ॥","पूर्व जनम का वैरी आया, कमठ असुर ने मेघ डिगाया ॥ ६ ॥","घोर घटा नभ में छिटकाई, मूसलधार वृष्टि बरसाई ॥ ७ ॥","शिला गिरे अति गर्जन भारी, पवन चले अति तीव्र विकारी ॥ ८ ॥"]},{lines:["नासाग्र दृष्टि प्रभु धारी, अचल रहे जैसे गिरि भारी ॥ ९ ॥","जल से भर गई धरती सारी, प्रभु पद छूने आई जल-धारी ॥ १० ॥","धरणेन्द्र पद्मावती धाये, फण फैलाय छत्र सजाये ॥ ११ ॥","कमठ हार कर शीश झुकायो, प्रभु ने समता भाव बढ़ायो ॥ १२ ॥"]},{lines:["घातिया कर्म किए सब क्षीना, प्रगट भयो केवल सुख लीना ॥ १३ ॥","अहिच्छत्र तब तीर्थ कहायो, सकल जगत में अतिशय छायो ॥ १४ ॥","मंदिर भव्य बन्यो सुखकारी, पद्मावती माँ पहरेदारी ॥ १५ ॥","अतिशयकारी पारस स्वामी, दूर करें संकट सब नामी ॥ १६ ॥"]},{lines:["जो जन अहिच्छत्र में जावे, मनवांछित सब फल सो पावे ॥ १७ ॥","रोग-दोष सब दूर नसावें, भूत-प्रेत सब भाग जावें ॥ १८ ॥","सर्प-भय विष-दोष निवारक, पार्श्वनाथ संकट के तारक ॥ १९ ॥","अहिच्छत्र की माटी पावन, जो छुए होवे मन भावन ॥ २० ॥"]},{lines:["चारों ओर हरियाली सोहे, शांत वातावरण मन मोहे ॥ २१ ॥","अखंड ज्योति मंदिर में जागे, अंधकार अज्ञान का भागे ॥ २२ ॥","अभिषेक जल मस्तक धारें, जनम-जनम के पाप निवारें ॥ २३ ॥","धूप दीप नैवेद्य चढ़ावें, भाव भक्ति से चालीसा गावें ॥ २४ ॥"]},{lines:["तेईसवें तीर्थंकर कहलाये, जग को मुक्ति मार्ग दिखाये ॥ २५ ॥","अहिंसा दया का दीप जलाया, जियो और जीने दो समझाया ॥ २६ ॥","चतुर्विध संघ की स्थापना कीनी, मुनि-श्रावक को शिक्षा दीनी ॥ २७ ॥","सम्मेद शिखर से मोक्ष सिधारे, कोटि-कोटि मुनि भव से तारे ॥ २८ ॥"]},{lines:["अहिच्छत्र पार्श्वनाथ गुण गाऊँ, चरण-शरण में शीश नवाऊँ ॥ २९ ॥","मैं पापी प्रभु शरण तिहारी, मेटो मेरी विपदा भारी ॥ ३० ॥","धन-वैभव विद्या सुख दीजे, सम्यग्दर्शन उज्ज्वल कीजे ॥ ३१ ॥","जो चालीस दिन पाठ करावे, घर में मंगल मोद बढ़ावे ॥ ३२ ॥"]},{lines:["पुत्र-पौत्र सुख संपति पावे, संकट कोई पास न आवे ॥ ३३ ॥","दुखिया के सब दुःख मिटाते, बिगड़े काम प्रभु बन जाते ॥ ३४ ॥","सच्चे मन से जो कोई ध्यावे, भव-भव के बंधन कट जावे ॥ ३५ ॥","पारस प्रभु सम वीतराग, जो पूजे जागे अनुराग ॥ ३६ ॥"]},{lines:["अहिच्छत्र तीरथ महान, जहँ प्रगटे पारस भगवान ॥ ३७ ॥","कृपा करो प्रभु दीनदयाला, काटहु कर्मों का यह जाला ॥ ३८ ॥","नित प्रति पारस नाम जपूँ, पावन पद में चित्त रखूँ ॥ ३९ ॥","अहिच्छत्र के पार्श्व जिनेश, मेटो जग के सकल क्लेश ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["अहिच्छत्र पार्श्वनाथ को, ध्यावे जो मन लाय।","ऋद्धि-सिद्धि सुख-संपदा, सहज मिले घर आय ॥","कमठ-निवारक पारस प्रभु, देहु ज्ञान प्रकाश।","चरण कमल में दास के, पूरण हो अभिलाष ॥"]}]},"parshvanath-chalisa-badagaon":{id:"parshvanath-chalisa-badagaon",category:"chalisa",title:"श्री पार्श्वनाथ चालीसा (बड़ागांव)",subtitle:"त्रिलोक तीर्थ बड़ागांव पार्श्वनाथ चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["बड़ागांव त्रिलोक तीर्थ, पावन अतिशय धाम।","पार्श्वनाथ चिंतामणि, वंदूँ आठों याम ॥","बागपत पावन धरा, प्रगटे पारस नाथ।","शरणागत के शीश पर, राखो प्रभु निज हाथ ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय जय पार्श्वनाथ दयाला, बड़ागांव के दीनदयाला ॥ १ ॥","चिंतामणि पारस कहलाते, भक्तों के संकट हर जाते ॥ २ ॥","अतिशयकारी मूरत सोहे, दिव्य तेज लख जग मन मोहे ॥ ३ ॥","भूमि खोदकर मूरत पाई, जन-जन में जयकार मचाई ॥ ४ ॥"]},{lines:["त्रिलोक तीर्थ धाम सुहावन, तीनों लोक का रूप पावन ॥ ५ ॥","नंदीश्वर जिन धाम बनायो, शिखर गगन में फहरायो ॥ ६ ॥","सुमेरु पर्वत सम रचना भारी, देखत थकित होंय नर-नारी ॥ ७ ॥","पार्श्वनाथ स्वामी सुखकारी, काटत जनम-मरण की बारी ॥ ८ ॥"]},{lines:["जो नर बड़ागांव में आवें, चिंतामणि का दर्शन पावें ॥ ९ ॥","सकल मनोरथ पूरण होते, पाप-ताप सब धुलते धोते ॥ १० ॥","व्यापार में जो घाटा पावे, दर्शन कर धन-धान्य बढ़ावे ॥ ११ ॥","संतान हीन को सुत मिल जाता, निर्बल जन बलवान कहाता ॥ १२ ॥"]},{lines:["काल-सर्प का दोष नशावे, पारस प्रभु जब मन में ध्यावे ॥ १३ ॥","असाध्य रोग तुरंत मिटावें, कृपा-सिंधु पारस कहलावे ॥ १४ ॥","पद्मावती माता संग बिराजें, धरणेन्द्र देव चरण में साजे ॥ १५ ॥","अखंड दीप की ज्योति सुहानी, गूंजे मधुर जिनेंद्र की वाणी ॥ १६ ॥"]},{lines:["अभिषेक जल जो कोई छींटे, दुख-दारिद्र्य पल में बीटे ॥ १७ ॥","अष्टद्रव्य से पूजा कीजे, जन्म सफल निज कर लीजे ॥ १८ ॥","बड़ागांव अति पावन नगरी, मिटे जहाँ भक्तों की कगरी ॥ १९ ॥","शांति-धारा जो कोई करावे, परम शांति निज घर में पावे ॥ २० ॥"]},{lines:["कमठ-विनाशक पारस स्वामी, घट-घट वासी अंतरयामी ॥ २१ ॥","तीन लोक के नाथ कहावो, भटके नर को राह दिखावो ॥ २२ ॥","अहिंसा धर्म की ध्वजा उठाई, सत्य दया की जोत जलाई ॥ २३ ॥","राग-द्वेष मद-मोह नसाया, केवलज्ञान प्रकाश जगाया ॥ २४ ॥"]},{lines:["सम्मेद शिखर जा शिवपद पायो, सिद्धक्षेत्र जग को दिखलायो ॥ २५ ॥","बड़ागांव में अतिशय भारी, नित-प्रति आवें नर और नारी ॥ २६ ॥","मेला लगे जहाँ भारी-भारी, जय-जयकार करे संसारी ॥ २७ ॥","जो जन चालीसा चालीस दिन गावे, मनवांछित आनंद वो पावे ॥ २८ ॥"]},{lines:["संकट मोचन पारस नाथ, रखो सदा सिर पर निज हाथ ॥ २९ ॥","विद्या-बुद्धि का दान दीजिये, पावन सम्यक्त्व हृदय कीजिय ॥ ३० ॥","मोह-महामद नाश करो, आत्म-रस से हृदय भरो ॥ ३१ ॥","मैं अज्ञान शरण में आया, पारस प्रभु ने पार लगाया ॥ ३२ ॥"]},{lines:["दीन-हीन पर दया करो, ज्ञान-दीप उर में धरो ॥ ३३ ॥","घर-घर में सुख-शांति विराजे, पारस नाम सदा उर गाजे ॥ ३४ ॥","सब संकट से मुझे बचाओ, भव-सागर से पार लगाओ ॥ ३५ ॥","बड़ागांव त्रिलोक की जय, पारस प्रभु हरते जग भय ॥ ३६ ॥"]},{lines:["पद्मावती माँ की जयकार, धरणेन्द्र देव करें उद्धार ॥ ३७ ॥","नित्य प्रति पारस चालीसा गाऊँ, जनम-जनम प्रभु भक्ति पाऊँ ॥ ३८ ॥","चरण-कमल में ध्यान लगाऊँ, मुक्ति-वधु का वर बन जाऊँ ॥ ३९ ॥","बड़ागांव के श्री जिनराज, सिद्ध करो प्रभु मेरे काज ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["बड़ागांव के पारस प्रभु, चिंतामणि अवतार।","जो जन चरणों में नमे, होवे बेड़ा पार ॥","त्रिलोक तीर्थ धाम में, गूंजे पारस नाम।","सब सुख संपति दीजिए, पूरण कीजे काम ॥"]}]},"bahubali-chalisa":{id:"bahubali-chalisa",category:"chalisa",title:"श्री बाहुबली चालीसा",subtitle:"प्रथम कामदेव भगवान बाहुबली स्वामी ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["शीश नवा अरिहंत को, सिद्धन करूं प्रणाम।","बाहुबली प्रभु की कृपा, पूरण हो सब काम ॥","ऋषभदेव के लाड़ले, भरत-अनुज बलवान।","श्रवणबेलगोला मही, विराजे भगवान ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय बाहुबली बल के धामा, कामदेव तुम अनुपम नामा ॥ १ ॥","पौरुष के प्रतिमान जिनेशा, काटो प्रभु जी सकल कलेशा ॥ २ ॥","पोदनपुर में राज सँभाला, न्याय नीति का दीप उझाला ॥ ३ ॥","चक्ररत्न जब चक्रवर्ती पाया, छह खंडों पर राज जमाया ॥ ४ ॥"]},{lines:["भरत-बाहुबली युद्ध ठना जब, तीन युद्ध में जीते प्रभु तब ॥ ५ ॥","दृष्टि-युद्ध में नयन न मोड़े, जल-युद्ध में जल-कण छोड़े ॥ ६ ॥","मल्ल-युद्ध में भरत उठाया, तब मन में वैराग्य जगाया ॥ ७ ॥","यह संसार असार अनित्य, क्षणभंगुर सब राज प्रपञ्च ॥ ८ ॥"]},{lines:["भरत को क्षमादान दे दीना, तजकर राज संन्यास लीना ॥ ९ ॥","वन में जाकर खड़े हुवे प्रभु, कायोत्सर्ग मुद्रा साधे विभु ॥ १० ॥","एक वर्ष पर्यन्त तपस्या, अडिग रहे जैसे गिरि शृंगा ॥ ११ ॥","देह-लता पर बेल चढ़ाई, सर्प-बिच्छू ने बांबी बनाई ॥ १२ ॥"]},{lines:["पक्षी बैठ घोंसला कीन्हा, प्रभु ने किंचित ध्यान न दीन्हा ॥ १३ ॥","मान कषाय का लेश रहा जब, भरत नमन करने आये तब ॥ १४ ॥","‘यह भूमि तो भरत की भाई’, भरत ने आ प्रभुता गाई ॥ १५ ॥","जैसे ही अभिमान बिलाया, तत्क्षण केवलज्ञान उपाया ॥ १६ ॥"]},{lines:["प्रथम मोक्षगामी कहलाये, सिद्धक्षेत्र शिवपद को पाये ॥ १७ ॥","श्रवणबेलगोला के माहीं, चामुंडराय ने प्रतिमा कराई ॥ १८ ॥","सत्तावन फुट मूरत सोहे, कोटि-कोटि भविकों को मोहे ॥ १९ ॥","महामस्तकाभिषेक जब होवे, देव-इंद्र आ मस्तक धोवे ॥ २० ॥"]},{lines:["दूध दही केशर की धारा, अद्भुत दृश्य लगे जग सारा ॥ २१ ॥","गोम्मटेश्वर प्रभु नाम तुम्हारा, पापी जन को भव से तारा ॥ २२ ॥","जो जन बाहुबली गुण गावे, अष्टसिद्धि नवनिधि घर पावे ॥ २३ ॥","अहंकार का नाश करावें, समता रस उर में बरसावें ॥ २४ ॥"]},{lines:["शत्रु मित्र सम भाव जगावें, आतम-विद्या सहज सिखावें ॥ २५ ॥","त्याग तपस्या के अवतारी, जय बाहुबली प्रभु अविकारी ॥ २६ ॥","काम-क्रोध के नाशन हारे, भव-भव के संताप विडारे ॥ २७ ॥","निर्भय पद के दाता स्वामी, नमो नमो प्रभु अंतरयामी ॥ २८ ॥"]},{lines:["जो नर चालीसा चित्त लावे, जनम-मरण का कष्ट नशावे ॥ २९ ॥","बाहुबली प्रभु कृपा कीजे, सम्यग्ज्ञान हृदय में दीजे ॥ ३० ॥","तन-बल मन-बल आत्म-बल, तुम सम बने हृदय निर्मल ॥ ३१ ॥","रोग-शोक सब दूर भगाओ, जीवन में सुख-शांति लाओ ॥ ३२ ॥"]},{lines:["गृहस्थ धर्म का मर्म सिखाया, श्रमण धर्म का रूप दिखाया ॥ ३३ ॥","त्याग बिना नहिं मुक्ति पावे, बाहुबली संदेश सुनावें ॥ ३४ ॥","अहिंसा परम धर्म का सार, बाहुबली जय जयकार ॥ ३५ ॥","नित प्रति बाहुबली को ध्याऊँ, पावन चरण-शरण सुख पाऊँ ॥ ३६ ॥"]},{lines:["गोम्मट प्रभु संकट के हारी, जयति-जयति जग मंगलकारी ॥ ३७ ॥","हाथ जोड़ विनती प्रभु मोरी, भव-बंधन की काटो डोरी ॥ ३८ ॥","विद्यासागर सम मुनि ध्यावें, कुंदकुंद प्रभु महिमा गावें ॥ ३९ ॥","बाहुबली भगवान की जय, निर्भय पद दे हरहु भय ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["बाहुबली भगवान को, जो ध्यावे दिन-रैन।","अहंकार सब दूर हो, पावे शाश्वत चैन ॥","गोम्मटेश्वर जिनराज नमो, पूरण कीजे काज।","आत्म-ज्ञान प्रकाश दे, राखो मेरी लाज ॥"]}]},"padmavati-chalisa":{id:"padmavati-chalisa",category:"chalisa",title:"श्री पद्मावती चालीसा",subtitle:"भगवान पार्श्वनाथ शासनदेवी पद्मावती माता ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["पार्श्वनाथ प्रभु के चरण, ध्याऊँ बारंबार।","पद्मावती माता करहु, नैया भव से पार ॥","धरणेन्द्र की पटरानी, शासनदेवी नाम।","शरणागत की रक्षा कर, पूरण कीजे काम ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय जय पद्मावती वरदानी, पार्श्वनाथ की सेविका मानी ॥ १ ॥","कमठ-उपसर्ग निवारण कीन्हा, पारस प्रभु को आसन दीन्हा ॥ २ ॥","कमल नयन पद्मासन साजे, मुकुट मनोहर शीश विराजे ॥ ३ ॥","चार भुजायें अतिशय सोहें, अंकुश पाश फल मन मोहें ॥ ४ ॥"]},{lines:["स्वर्ण वर्ण तन ज्योति अपारा, कोटि चन्द्र सम तेज पसारा ॥ ५ ॥","सर्प-छत्र मस्तक पर सोहे, पद्मावती छवि जग को मोहे ॥ ६ ॥","जो ध्यावे पद्मावती माता, सुख-संपति वैभव सब पाता ॥ ७ ॥","विपदा-संकट सब टल जावें, मात कृपा जब घर में पावें ॥ ८ ॥"]},{lines:["दुष्ट-ग्रहों की पीड़ा भागे, शुभ मंगल का दीपक जागे ॥ ९ ॥","व्यापार में लाभ करावे, निर्धन को धनवान बनावे ॥ १० ॥","संतान हीन को गोदी भारे, दुखियों के सब संकट टारे ॥ ११ ॥","विद्या बुद्धि यश की दाता, जय जय पद्मावती माता ॥ १२ ॥"]},{lines:["अहिच्छत्र तिजारा धाम, गूंजे मात तुम्हारा नाम ॥ १३ ॥","सम्मेद शिखर जी में बिराजें, घंटा-घड़ियाल मधुर बाजे ॥ १४ ॥","अष्टगंध से पूजा कीजे, लाल पुष्प माता को दीजे ॥ १५ ॥","धूप दीप नैवेद्य सजावें, आरती मंगल भाव सुनावें ॥ १६ ॥"]},{lines:["काल-सर्प का दोष नशाती, जीवन में सुख-शांति लाती ॥ १७ ॥","भूत-प्रेत पिशाच डरावें, पद्मावती नाम से जावें ॥ १८ ॥","रोग-शोक सब दूर भगावे, जो माता की शरण में आवे ॥ १९ ॥","भक्त-वत्सला दया की मूरत, शांत सौम्य कल्याणी सूरत ॥ २० ॥"]},{lines:["पार्श्वनाथ के संग विराजो, जिनशासन की शोभा साजो ॥ २१ ॥","सम्यक्त्व रक्षा मात कराती, मिथ्यामत का नाश कराती ॥ २२ ॥","जो चालीस दिन पाठ करावे, मात कृपा निज घर में पावे ॥ २३ ॥","पुत्र-पौत्र सुख संपति बाढ़े, विघ्न भागें सब दुःख काढ़े ॥ २४ ॥"]},{lines:["मैं अज्ञान दास हूँ तेरा, काटो जनम-मरण का फेरा ॥ २५ ॥","भूल-चूक सब क्षमा करीजे, अपनी पावन शरण में लीजे ॥ २६ ॥","सच्चे मन से जो कोई ध्यावे, जीवन में आनंद बढ़ावे ॥ २७ ॥","घर में अन्न-वस्त्र भर दीजे, सुख-संतोष का सागर कीजे ॥ २८ ॥"]},{lines:["जयति जयति पद्मावती देवी, सुर-नर मुनिजन चरणन सेवी ॥ २९ ॥","धरणेन्द्र संग मंगलकारी, रक्षा करतीं सदा हमारी ॥ ३० ॥","अंधकार अज्ञान नशाओ, ज्ञान-दीप उर बीच जलाओ ॥ ३१ ॥","धर्म-कर्म में मन को लगाओ, सन्मार्ग की राह दिखाओ ॥ ३२ ॥"]},{lines:["पारस प्रभु की भक्ति पाऊँ, जनम-जनम गुण तेरे गाऊँ ॥ ३३ ॥","पद्मावती माता कल्याणी, तेरी महिमा सब जग जानी ॥ ३४ ॥","ह्रीं क्लीं ब्लूं मन्त्र सुहावन, जपत मिटे सब पाप सुपावन ॥ ३५ ॥","शरणागत की लाज निभाओ, बिगड़ी बात तुरंत बनाओ ॥ ३६ ॥"]},{lines:["जय पद्मावती जय सुखदाई, भक्तों ने जय-जयकार मचाई ॥ ३७ ॥","सकल मनोरथ पूरण कीजे, भक्ति का वरदान ही दीजे ॥ ३८ ॥","निसिदिन मात तुम्हारा ध्यान, पावें सुख-वैभव निर्वान ॥ ३९ ॥","पद्मावती चालीसा गावें, भव-सागर से पार लगावें ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["पद्मावती माता कृपा, कीजे सदा सहाय।","संकट-विपदा सब टलें, मंगल मोद बढ़ाय ॥","पार्श्वनाथ के चरण में, पद्मावती का वास।","‘जिनवाणी’ उर में रहे, पूरण हो अभिलाष ॥"]}]},"saraswati-chalisa":{id:"saraswati-chalisa",category:"chalisa",title:"श्री जिनवाणी / सरस्वती चालीसा",subtitle:"द्वादशांग जिनवाणी माता ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["ज्ञानमयी जिन भारती, वंदूँ बारंबार।","बुद्धि विशुद्ध प्रदान कर, मेटहु मोहांधकार ॥","द्वादशांग जिनवाणी माता, भव-सागर से तार।","अक्षर-अक्षर मोक्षमय, सुख की खान अपार ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय जिनवाणी ज्ञान की खानी, तीन लोक में अमृत वाणी ॥ १ ॥","अरिहंतों के मुख से निकली, गणधरों ने उर में धर ली ॥ २ ॥","आचार्य परम्परा से आई, जग को मुक्ति-राह दिखाई ॥ ३ ॥","द्वादशांग जिनवाणी माता, तू है भव-जल तारण-त्राता ॥ ४ ॥"]},{lines:["प्रथमानुयोग चरित सिखलावे, पुण्य-पाप का भेद बतावे ॥ ५ ॥","करणानुयोग लोक-गति गाये, कर्म-प्रकृति की चाल दिखाये ॥ ६ ॥","चरणानुयोग आचार सिखावे, श्रावक-मुनि का व्रत बतलावे ॥ ७ ॥","द्रव्यानुयोग तत्व समझाये, आत्मा का निज रूप लखाये ॥ ८ ॥"]},{lines:["षट्द्रव्यों का ज्ञान करावे, सात तत्व का भेद बतावे ॥ ९ ॥","जीव-अजीव की भिन्नता गाये, नय प्रमाण की बात समझाये ॥ १० ॥","स्याद्वाद की ध्वजा उड़ाई, अनेकांत की जोत जलाई ॥ ११ ॥","कुंदकुंद ने समयसार लिखा, अमृतचंद्र ने टीका सिखा ॥ १२ ॥"]},{lines:["षट्खण्डागम धवला ग्रंथ, खोल दिया शिव-सुख का पंथ ॥ १३ ॥","तत्त्वार्थ सूत्र उमास्वामी गायो, मोक्षमार्ग जग को समझायो ॥ १४ ॥","जो जिनवाणी को नित ध्यावे, सम्यग्दर्शन पावन पावे ॥ १५ ॥","मिथ्या ज्ञान-अंधेरा भागे, केवलज्ञान-सूर्य उर जागे ॥ १६ ॥"]},{lines:["अक्षर-अक्षर में अमृत धारा, भव-आतप से तारे सारा ॥ १७ ॥","श्रुतपंचमी पर्व सुहावन, जिनवाणी पूजा अति पावन ॥ १८ ॥","शास्त्र दान जो नर देवे, स्वर्ग-मोक्ष पदवी सो लेवे ॥ १९ ॥","अंग-पूर्व का ज्ञान विशाला, तू ही माँ भव-तारनहारा ॥ २० ॥"]},{lines:["काव्य-व्याकरण न्याय सिखावे, वीतरागता उर उपजावे ॥ २१ ॥","राग-द्वेष मद-मोह नसावे, शांत सुधा रस खूब बहावे ॥ २२ ॥","विद्या-बुद्धि का दान तू देती, मंदबुद्धि को ज्ञानी करती ॥ २३ ॥","वाक्-सिद्धि प्रतिभा चमकावे, जन-मन में आनंद बढ़ावे ॥ २४ ॥"]},{lines:["जो चालीसा प्रेम से गावे, सकल मनोरथ पूर्ण पावे ॥ २५ ॥","परीक्षा में विजय दिलावे, यश-कीर्ति सब ओर बढ़ावे ॥ २६ ॥","मैं अज्ञान शरण में आया, माँ जिनवाणी ने अपनाया ॥ २७ ॥","मेरी मति को निर्मल कीजे, सम्यग्ज्ञान हृदय में दीजे ॥ २८ ॥"]},{lines:["सत्य-अहिंसा धर्म सिखाओ, आतम-विद्या सहज पढ़ाओ ॥ २९ ॥","जिनवाणी सम और न कोई, भव-दुख मेटन हारी सोई ॥ ३० ॥","अक्षर-मात्रा बिंदु विहीना, क्षमा करो माँ करुणा-लीना ॥ ३१ ॥","चरण कमल में शीश नवाऊँ, नित्य प्रति माँ के गुण गाऊँ ॥ ३२ ॥"]},{lines:["पूजा-अर्घ्य चढ़ाऊँ भारी, जय जय जिनवाणी महतारी ॥ ३३ ॥","घर-घर में जिनवाणी विराजे, स्वाध्याय का नगाड़ा बाजे ॥ ३४ ॥","शास्त्र-सभा में अमृत बरसे, भविक जन प्रभु दर्शन तरसे ॥ ३५ ॥","विद्या-बुद्धि समृद्धि की दाता, जयति-जयति सरस्वती माता ॥ ३६ ॥"]},{lines:["पाप-मलिनता सब हर लीजे, वीतराग-पद मुझको दीजे ॥ ३७ ॥","निसिदिन शरण तुम्हारी माँगी, बन जाऊँ मैं सच्चा त्यागी ॥ ३८ ॥","द्वादशांग जिनवाणी माई, तेरी महिमा जग में छाई ॥ ३९ ॥","चालीसा चालीस दिन गावे, निश्चय मुक्ति-महल को पावे ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["जिनवाणी माता नमो, ज्ञान-सिंधु सुख-धाम।","चरण कमल में शीश धर, पूरण कीजे काम ॥","जा वाणी के ज्ञान ते, सूझे लोकालोक।","सो वाणी मस्तक धरूँ, सदा देत हूँ ढोक ॥"]}]},"vidyasagar-chalisa":{id:"vidyasagar-chalisa",category:"chalisa",title:"आचार्य श्री विद्यासागर चालीसा",subtitle:"संत शिरोमणि युगप्रवर्तक आचार्य श्री विद्यासागर जी चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["ज्ञान-सिंधु समता-धनी, वीतराग अवतार।","विद्यासागर गुरु नमो, वंदन बारंबार ॥","ज्ञानसागर गुरु के शिष्य, कुंदकुंद के रूप।","कलिकाल में मुनिराज सम, वीतरागता भूप ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय विद्यासागर मुनिराजा, पूर्ण करो सेवक के काजा ॥ १ ॥","सद्लगगा पावन जन्म स्थान, मल्लप्पा श्रीमंत सुजान ॥ २ ॥","श्रीमती मात की कोख सुहाई, विद्याधर ने महिमा पाई ॥ ३ ॥","बचपन से वैराग्य समाया, खेल-कूद सब छोड़ छुड़ाया ॥ ४ ॥"]},{lines:["अजमेर में मुनि दीक्षा लीनी, ज्ञानसागर ने कृपा कीनी ॥ ५ ॥","कठिन परीषह सब सह डारे, तप-बल से निज कर्म विदारे ॥ ६ ॥","निशिदिन आत्म-ध्यान लवलीन, वीतराग समता आधीन ॥ ७ ॥","मौन साधना व्रत अनुकूला, भू-शयन कंटक सम फूला ॥ ८ ॥"]},{lines:["एक बार ही भोजन पाते, अल्पाहार जल तृप्त कराते ॥ ९ ॥","पैदल चले सकल भू-मंडल, तीर्थों का कीन्हा उद्धार ॥ १० ॥","कुंडलपुर में बड़े बाबा का, मंदिर भव्य बनवायो न्यारा ॥ ११ ॥","नेमावर में नर्मदा तीरे, त्रिकाल चौबीसी मंदिर धीरे ॥ १२ ॥"]},{lines:["हथकरघा का मार्ग दिखाया, मूक माटी महाकाव्य बनाया ॥ १३ ॥","गौ-शालाएं खूब खुलवाई, भारत की संस्कृति जगाई ॥ १४ ॥","प्रतिभास्थली संस्कार सिखाये, नारी शक्ति के मान बढ़ाये ॥ १५ ॥","युवा वर्ग को दिशा दिखाई, संयम की महत्ता समझाई ॥ १६ ॥"]},{lines:["कुंदकुंद की वाणी गाई, जन-जन में समता फैलाई ॥ १७ ॥","आचार्य पद की शोभा बढ़ाई, संघ बड़ा अनुशासन छाई ॥ १८ ॥","मुनि-आर्यिका संघ अपारा, सब पर गुरुवर कृपा-धारा ॥ १९ ॥","डोंगरगढ़ चंद्रगिरि माहीं, सल्लेखना कीन्ह मन माहीं ॥ २० ॥"]},{lines:["तीन दिवस का अनशन कीन्हा, समाधिमरण सहज रस लीना ॥ २१ ॥","देवलोक सिधारे स्वामी, जय विद्यासागर अंतरयामी ॥ २२ ॥","जो जन गुरुवर को नित ध्यावे, जीवन में संयम सुख पावे ॥ २३ ॥","काम-क्रोध मद-मोह विनाशी, विद्यासागर ज्ञान-प्रकाशी ॥ २४ ॥"]},{lines:["गुरुवर की मूरत उर धारी, संकट कटे विपत्ति भारी ॥ २५ ॥","रोग-दोष सब दूर नसावें, गुरु-चरणों में जो सिर नावें ॥ २६ ॥","विद्या बुद्धि विवेक बढ़ावें, आतम-विद्या सहज सिखावें ॥ २७ ॥","राष्ट्र-संत जग में कहलाये, प्राणी मात्र पे दया लखाये ॥ २८ ॥"]},{lines:["जो चालीसा चालीस दिन गावे, गुरु कृपा से सुख सब पावे ॥ २९ ॥","पुत्र-पौत्र संपति घर आवे, विघ्न-बाधा सब मिट जावे ॥ ३० ॥","मैं अज्ञान शरण में आया, गुरुवर ने मोक्षमार्ग दिखाया ॥ ३१ ॥","अपनी दया दृष्टि बरसाओ, भव-सागर से पार लगाओ ॥ ३२ ॥"]},{lines:["सच्चे गुरु तुम जग में तारे, अंधकार में दीप उजारे ॥ ३३ ॥","‘समयसागर’ को पट्ट बिठाया, संघ-भार उन पर सँभलाया ॥ ३४ ॥","गुरुवर की शिक्षा न भूलें, धर्म-मार्ग पर नित-प्रति झूलें ॥ ३५ ॥","अहिंसा परमो धर्म का पाठ, विद्यासागर की महिमा ठाठ ॥ ३६ ॥"]},{lines:["चरण कमल में शीश नवाऊँ, जनम-जनम गुरु-भक्ति पाऊँ ॥ ३७ ॥","विद्यासागर गुरु अमर हमारे, भविक जनों के प्राण पियारे ॥ ३८ ॥","जय जय विद्यासागर स्वामी, तीन लोक में नामी स्वामी ॥ ३९ ॥","चालीसा जो प्रेम से गाये, वीतराग पद निश्चित पाये ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["विद्यासागर गुरु चरण में, कोटि-कोटि परनाम।","समाधि-मरण कर शिव गये, पूरण कीजे काम ॥","गुरुवर का संदेश सदा, जीवन में अपनाएँ।","सत्य अहिंसा धर्म से, भव-भव पार लगाएँ ॥"]}]},"gautam-ganadhar-chalisa":{id:"gautam-ganadhar-chalisa",category:"chalisa",title:"श्री गौतम गणधर चालीसा",subtitle:"भगवान महावीर के प्रथम गणधर स्वामी ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["महावीर के चरण में, गौतम कीन्हे ध्यान।","गणधर पद पावन लहे, सकल शास्त्र के ज्ञान ॥","इंद्रभूति विप्र कुल, मान गलित जब भाय।","द्वादशांग की रचना करी, वंदूँ शीश नवाय ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय गौतम गणधर सुखदाई, महावीर के शिष्य बड़ाई ॥ १ ॥","इंद्रभूति था नाम तुम्हारा, वेदों का था ज्ञान अपारा ॥ २ ॥","पावापुर में मान बढ़ाया, पांच सौ शिष्यन संग सिधाया ॥ ३ ॥","समवशरण जब पहुंचे स्वामी, मान-स्तंभ लख शीश नवामी ॥ ४ ॥"]},{lines:["गर्व-गुमान तुरंत गिलाया, महावीर के शरण में आया ॥ ५ ॥","दीक्षा ले मुनि-धर्म सम्हाला, क्षण में ज्ञान-सूर्य उजियाला ॥ ६ ॥","प्रथम गणधर पदवी पाई, द्वादशांग जिनवाणी गाई ॥ ७ ॥","दिव्यध्वनी जो खिरी प्रभु की, भाषा रूप दीन्ह मुनिवर की ॥ ८ ॥"]},{lines:["अंग-पूर्व की रचना कीनी, भव्य जनों को शिक्षा दीनी ॥ ९ ॥","अष्ट महाऋद्धिधारी स्वामी, आकाशगामी अंतरयामी ॥ १० ॥","अक्षीण महानस ऋद्धि सुहाई, थाली से सब सेना खाई ॥ ११ ॥","चार ज्ञान के धारी मुनिवर, वीतराग समता के सागर ॥ १२ ॥"]},{lines:["महावीर प्रभु जब शिव सिधारे, गौतम ने तब नैन उघारे ॥ १३ ॥","प्रभु-वियोग से अंतर जागा, राग-स्नेह का बंधन भागा ॥ १४ ॥","दीपावली की पावन राती, केवलज्ञान प्रगट्यो सुख-पाती ॥ १५ ॥","चौदह वर्ष विहार कराया, जन-जन को जिनधर्म सिखाया ॥ १६ ॥"]},{lines:["गुणावा पावन तीर्थ सुहावन, जहां से मोक्ष गये मुनि पावन ॥ १७ ॥","अष्टकर्म का नाश कराया, सिद्धालय में वास उपाया ॥ १८ ॥","गौतम स्वामी ऋद्धि के दाता, सब संकट के नाशन त्राता ॥ १९ ॥","जो जन गौतम नाम उचारे, दारिद्र्य दुःख पल में विडारे ॥ २० ॥"]},{lines:["विद्या बुद्धि रिद्धि सिद्धा, गौतम चरण मिले निर्विधा ॥ २१ ॥","लक्ष्मी का भण्डार भरावे, जो प्रातः गौतम गुण गावे ॥ २२ ॥","अन्न-वस्त्र की कमी न होवे, पाप-ताप सब धुलते धोवे ॥ २३ ॥","व्यापार में लाभ करावे, कोटि-कोटि संपति बरसावे ॥ २४ ॥"]},{lines:["जो चालीसा प्रेम से गावे, मनोकामना पूरण पावे ॥ २५ ॥","रोग-दोष सब दूर नसावे, गौतम नाम महाफल पावे ॥ २६ ॥","दीपावली पर पूजा कीजे, गौतम नाम बही पर लीजे ॥ २७ ॥","संवत का प्रारंभ सुहावे, गौतम कृपा से लाभ कमावे ॥ २८ ॥"]},{lines:["सकल ऋद्धि के स्वामी ध्याऊँ, पावन पद में चित्त लगाऊँ ॥ २९ ॥","मैं अज्ञान शरण में आया, गौतम प्रभु ने पार लगाया ॥ ३० ॥","मोह-महामद नाश करो जी, सम्यग्दर्शन उर में धरो जी ॥ ३१ ॥","अहिंसा सत्य दया का सार, गौतम स्वामी जय जयकार ॥ ३२ ॥"]},{lines:["श्रुत-ज्ञानामृत खूब पिलाया, जग को मुक्ति-मार्ग दिखाया ॥ ३३ ॥","मुनि संघ के नायक स्वामी, नमो नमो त्रिभुवन के नामी ॥ ३४ ॥","हाथ जोड़ विनती प्रभु मोरी, काटो भव-भव की यह डोरी ॥ ३५ ॥","सच्चे मन से जो कोई ध्यावे, जीवन में आनंद बढ़ावे ॥ ३६ ॥"]},{lines:["घर में सुख-शांति बरसाओ, बिगड़े काम तुरंत बनाओ ॥ ३७ ॥","गौतम स्वामी ज्ञान के सागर, कृपा करो मुझ पर करुणाकर ॥ ३८ ॥","निसिदिन गौतम नाम पुकारूँ, जनम-जनम का ताप निवारूँ ॥ ३९ ॥","चालीसा चालीस दिन गाये, सिद्ध-लोक में वास सो पाये ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["गौतम स्वामी के चरण, ध्यावे जो नर-नार।","ऋद्धि-सिद्धि संपदा लहे, पावे पद निर्वार ॥","ॐ ह्रीं श्रीं गौतम गणधराय नमः, जपे जो आठों याम।","सकल अमंगल दूर हों, पूरण हो सब काम ॥"]}]},"sammed-shikhar-chalisa":{id:"sammed-shikhar-chalisa",category:"chalisa",title:"श्री सम्मेद शिखर जी चालीसा",subtitle:"शाश्वत सिद्धक्षेत्र २० तीर्थंकर निर्वाण भूमि ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["बीस जिनेश्वर मोक्ष गये, जहां से सिद्ध अनंत।","सम्मेद शिखर पावन मही, वंदूँ बारंबार ॥","पारसनाथ पहाड़ सुहावन, झारखंड का धाम।","एक बार वंदन करे, मिटे नरक का काम ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय सम्मेद शिखर गिरिराज, सिद्धक्षेत्र त्रिभुवन के ताज ॥ १ ॥","शाश्वत तीरथ परम पुनीता, कोटि-कोटि मुनि कर्म विजीता ॥ २ ॥","बीस तीर्थंकर शिवपद पाये, पद-चिन्हों की महिमा छाये ॥ ३ ॥","अजित, संभव, अभिनंदन स्वामी, सुमति, पद्मप्रभ अंतरयामी ॥ ४ ॥"]},{lines:["सुपार्श्व, चंद्रप्रभ, पुष्पदंता, शीतल, श्रेयांस मुनि भगवंता ॥ ५ ॥","विमल, अनंत, धर्म जिनराया, शांति, कुंथु, अरह पद पाया ॥ ६ ॥","मल्लि, मुनिसुव्रत, नमि जिनराजा, पार्श्वनाथ सिद्धन के ताज़ा ॥ ७ ॥","चौबीस में से बीस जिनेशा, इस गिरि से काटे सब क्लेशा ॥ ८ ॥"]},{lines:["मधुवन नगरी तलहटी सोहे, धर्मशालाएं मन को मोहे ॥ ९ ॥","प्रातःकाल वंदना ध्यावें, नौ कोस की परिक्रमा जावें ॥ १० ॥","गंधर्व नाला शीतल पानी, अमृत सम मीठी जिनवाणी ॥ ११ ॥","शीतल नाला चढ़ाई भारी, जयकारा बोलें नर-नारी ॥ १२ ॥"]},{lines:["पारसनाथ की टोंक सुहाई, स्वर्ण छत्र की छटा लखाई ॥ १३ ॥","जल मंदिर में पूजा कीजे, अर्घ्य चढ़ाकर समता लीजे ॥ १४ ॥","ढोलक मंजीरा झांझ बजावें, भक्ति-भाव से चालीसा गावें ॥ १५ ॥","सम्मेद शिखर की पावन माटी, मस्तक धरे कटे भव-घाटी ॥ १६ ॥"]},{lines:["जो जन एक बार चढ़ जावे, नरक-निगोद की गति नहिं पावे ॥ १७ ॥","असंख्य मुनिवर यहाँ समाये, तप के बल से मोक्ष सिधाये ॥ १८ ॥","डोलियों पर वृद्ध सिधारे, जय-जय पारसनाथ पुकारे ॥ १९ ॥","जंगल में मंगल दरसावे, शांत तपोभूमि मन भावे ॥ २० ॥"]},{lines:["चारों ओर हरियाली छाई, पक्षी करें प्रभु की प्रभुताई ॥ २१ ॥","टोंक-टोंक पर शीश नवावें, अष्टद्रव्य से अर्घ चढ़ावें ॥ २२ ॥","कपूर-आरती ज्योति जगावें, मनवांछित सब वैभव पावें ॥ २३ ॥","रोग-दोष सब दूर नसावें, शिखर वंदना जो नर पावें ॥ २४ ॥"]},{lines:["दुख-दारिद्र्य पल में मिट जावे, सुख-शांति घर में भर जावे ॥ २५ ॥","जो चालीसा चालीस दिन गावे, शिखर जी का फल वो पावे ॥ २६ ॥","सम्मेद शिखर की रक्षा कीजे, प्राणन से भी प्यारा कीजे ॥ २७ ॥","तीर्थ-रक्षा का संकल्प उठावें, जिनशासन की ध्वजा फहरावें ॥ २८ ॥"]},{lines:["मैं पापी प्रभु शरण तिहारी, वंदूँ बार-बार गिरि भारी ॥ २९ ॥","जन्म-मरण का फेरा काटो, आत्म-रस की गागर बाँटो ॥ ३० ॥","सम्यग्दर्शन पावन दीजे, निज आतम में लीन करीजे ॥ ३१ ॥","सम्मेद शिखर तीरथ सुखकारी, महिमा गावत दुनिया सारी ॥ ३२ ॥"]},{lines:["पारसनाथ प्रभु कृपा निधान, दीजे प्रभु जी आतम ज्ञान ॥ ३३ ॥","दूर-दूर से यात्री आवें, भाव सहित परिक्रमा लगावें ॥ ३४ ॥","चरण कमल में ध्यान लगाऊँ, मुक्ति-महल का पथ मैं पाऊँ ॥ ३५ ॥","सम्मेद शिखर की जय जयकार, बीस जिनेश्वर बेड़ा पार ॥ ३६ ॥"]},{lines:["अखंड ज्योति टोंकन पर जागे, अंधकार अज्ञान का भागे ॥ ३७ ॥","हाथ जोड़ विनती करूँ, सुनिये पारस नाथ।","भव-सागर में डूबते, पकड़ो मेरा हाथ ॥ ३८ ॥","निसिदिन शिखर जी को ध्याऊँ, अंत समय समाधि पाऊँ ॥ ३९ ॥"]},{lines:["चालीसा जो प्रेम से गाये, सिद्ध-पदवी निश्चित पाये ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["सम्मेद शिखर गिरिराज को, वंदूँ मन वच काय।","बीस जिनेश्वर की कृपा, सब संकट मिट जाय ॥","तीर्थराज सम्मेद शिखर, पावन परम पुनीत।","‘जिनवाणी’ सेवा करूँ, प्रभु चरणों में प्रीत ॥"]}]},"girnar-chalisa":{id:"girnar-chalisa",category:"chalisa",title:"श्री गिरनार जी तीर्थ चालीसा",subtitle:"भगवान नेमिनाथ दीक्षा, ज्ञान व मोक्ष कल्याणक क्षेत्र ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["उज्जयंत गिरिराज पर, नेमिनाथ जिनराय।","कोटि-कोटि मुनि मोक्ष गये, वंदूँ शीश नवाय ॥","सौराष्ट्र धरा पावन भली, जूनागढ़ विख्यात।","नेमिनाथ प्रभु के चरण, ध्याऊँ दिवस और रात ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय गिरनार महा सुखदाता, नेमिनाथ जग के पितु-माता ॥ १ ॥","बाईसवें तीर्थंकर स्वामी, तीन लोक के अंतरयामी ॥ २ ॥","समुद्रविजय शिवा के नंदन, शौरीपुर के राज-निकंदन ॥ ३ ॥","कृष्ण-बलराम के भाई प्यारे, बाल ब्रह्मचारी अविकारी ॥ ४ ॥"]},{lines:["राजुल संग ब्याह रचाया, बारात सजी मन हर्षाया ॥ ५ ॥","पशुओं की जब चीख सुनाई, करुणा प्रभु के उर में छाई ॥ ६ ॥","छोड़ दिया सब राज-सिंहासन, रथ मोड़ा तोड़ा जग-बंधन ॥ ७ ॥","गिरनार पर्वत पर आये, कठिन तपस्या ध्यान लगाये ॥ ८ ॥"]},{lines:["दीक्षा ज्ञान और मोक्ष पाया, गिरनार तीर्थ को चमकाया ॥ ९ ॥","उज्जयंत पर्वत की महिमा, अवर्णनीय गिरनार गरिमा ॥ १० ॥","प्रथम टोंक पर मंदिर सोहे, नेमिनाथ छवि मन को मोहे ॥ ११ ॥","सहस्राम्र वन पावन भारी, जहां तपस्या कीन्ह अपारी ॥ १२ ॥"]},{lines:["पाँचवीं टोंक शिखर अति पावन, नेमिनाथ मोक्ष कल्याणक भावन ॥ १३ ॥","दस हजार सीढ़ियाँ चढ़ जावें, भक्त-जन जयकारा लगावें ॥ १४ ॥","राजुल ने भी दीक्षा लीनी, गिरनार पर साधना कीनी ॥ १५ ॥","कोटि-कोटि मुनि यहाँ समाये, कर्म काट शिव-धाम सिधाये ॥ १६ ॥"]},{lines:["गिरनार की माटी चंदन, सुर-नर करते इसका वंदन ॥ १७ ॥","जो जन गिरनार पर जावे, भव-भव के बंधन कट जावे ॥ १८ ॥","रोग-कष्ट सब दूर नसावें, नेमिनाथ जब नाम सुनावें ॥ १९ ॥","पशु-रक्षा का पाठ पढ़ाया, जीव-दया का दीप जलाया ॥ २० ॥"]},{lines:["शौर्य और वैराग्य के संगम, नेमिनाथ प्रभु पावन अनुपम ॥ २१ ॥","ढोल नगाड़े मंदिर बाजे, आरती में जयकारा गाजे ॥ २२ ॥","पंचामृत अभिषेक करावें, अष्टद्रव्य से अर्घ चढ़ावें ॥ २३ ॥","गिरनार तीर्थ की रक्षा कीजे, तन-मन-धन अर्पण कर दीजे ॥ २४ ॥"]},{lines:["तीर्थ पर जो संकट आवे, जैन समाज ध्वजा फहरावे ॥ २५ ॥","नेमिनाथ प्रभु कृपा निधान, दीजे प्रभु जी आतम ज्ञान ॥ २६ ॥","जो चालीसा चालीस दिन गावे, मनवांछित सब वैभव पावे ॥ २७ ॥","पुत्र-पौत्र संपति घर आवे, दुःख-दरिद्र सब मिट जावे ॥ २८ ॥"]},{lines:["मैं अज्ञान शरण में आया, नेमिनाथ प्रभु ने अपनाया ॥ २९ ॥","काम-क्रोध मद-लोभ विनाशी, वीतराग आनंद-प्रकाशी ॥ ३० ॥","अहिंसा परम धर्म सिखलाया, जग को मुक्ति-राह दिखाया ॥ ३१ ॥","जूनागढ़ की पावन धरती, जहाँ गिरनार की शोभा सजती ॥ ३२ ॥"]},{lines:["चारों ओर पहाड़ सुहावन, दृश्य लगे अति पावन-भावन ॥ ३३ ॥","टोंकन-टोंकन शीश नवाऊँ, जनम-जनम प्रभु भक्ति पाऊँ ॥ ३४ ॥","हाथ जोड़ विनती प्रभु मोरी, काटो जनम-मरण की डोरी ॥ ३५ ॥","सच्चे मन से जो कोई ध्यावे, निश्चय मुक्ति-महल को पावे ॥ ३६ ॥"]},{lines:["नेमिनाथ प्रभु अंतरयामी, तुम हो मेरे पूरण स्वामी ॥ ३७ ॥","गिरनार तीर्थ की जय जयकार, नेमिनाथ प्रभु बेड़ा पार ॥ ३८ ॥","निसिदिन ध्यान धरूँ प्रभु तेरा, मेटो भव-सागर का फेरा ॥ ३९ ॥","चालीसा जो प्रेम से गाये, सिद्ध-लोक में वास सो पाये ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["गिरनार पर्वत नेमिनाथ, वंदूँ शीश नवाय।","सकल अमंगल दूर हों, सब संकट मिट जाय ॥","नेमिनाथ भगवान की, जो गावे चालीस।","ऋद्धि-सिद्धि संपदा लहे, पावे पद निर्भय अवनिपति ॥"]}]},"kundkund-chalisa":{id:"kundkund-chalisa",category:"chalisa",title:"आचार्य श्री कुंदकुंद स्वामी चालीसा",subtitle:"आगम शिरोमणि कलिकाल सर्वज्ञ कुंदकुंद देव ४० पद्य चालीसा",type:"structured",verses:[{lines:["॥ दोहा ॥"]},{lines:["सीमंधर प्रभु समवशरण, पहुंचे जो आकाश।","कुंदकुंद मुनिराज को, वंदन बारंबार ॥","कलिकाल सर्वज्ञ जग-गुरु, आगम के आधार।","समयसार पाहुड़ दिया, कीन्हा परमोपकार ॥"]},{lines:["॥ चौपाई ॥"]},{lines:["जय कुंदकुंद मुनीश्वर स्वामी, अध्यात्म के अंतरयामी ॥ १ ॥","दक्षिण भारत जन्म सुहावन, कौण्डकुन्द पुर पावन-भावन ॥ २ ॥","बाल्यकाल से वैराग्य लीना, जिन-दीक्षा धारण कर दीना ॥ ३ ॥","पद्मनंदि था नाम तुम्हारा, चारण ऋद्धिधारी अवतारा ॥ ४ ॥"]},{lines:["अन्तरिक्ष में गमन कराया, विदेह क्षेत्र समवशरण सिधाया ॥ ५ ॥","सीमंधर प्रभु दर्शन पायो, आठ दिवस तक अमृत न्हायो ॥ ६ ॥","साक्षात जिनवाणी सुनी भाई, भारत भूमि पे प्रगटाई ॥ ७ ॥","समयसार परमागम कीन्हा, शुद्धातम का दर्शन दीन्हा ॥ ८ ॥"]},{lines:["प्रवचनसार में ज्ञान बताया, नियमसार शिव-मार्ग दिखाया ॥ ९ ॥","पंचास्तिकाय अष्टपाहुड़ गाये, भव्य जनों के भाग जगाये ॥ १० ॥","द्रव्य-गुण-पर्याय समझाई, निश्चय-व्यवहार की संधि मिलाई ॥ ११ ॥","आत्मा को शुद्धात्मा भाया, देह भिन्न चैतन्य लखाया ॥ १२ ॥"]},{lines:["राग-द्वेष सब कर्म उपाधि, आत्मा तो आनंद समाधि ॥ १३ ॥","कुंदकुंद की वाणी अमृत, जो पीवे हो जाये अमरित ॥ १४ ॥","मंगलं भगवान वीरो, मंगलं गौतमो गणी।","मंगलं कुन्दकुन्दाद्यो, जैनधर्मोस्तु मंगलम् ॥ १५ ॥"]},{lines:["आचार्य परम्परा के सरताज, कुंदकुंद मुनिराज का राज ॥ १६ ॥","पोन्नूर पर्वत तप की भूमि, जहां विराजे कुंदकुंद स्वामी ॥ १७ ॥","चरण पादुका पूजत भाई, मनवांछित सब संपति पाई ॥ १८ ॥","जो कुंदकुंद ग्रंथ नित बांचे, सम्यग्दर्शन उर में नाचे ॥ १९ ॥"]},{lines:["मिथ्यामत का अंधकार भागे, केवलज्ञान प्रकाश उर जागे ॥ २० ॥","अमृतचंद्र ने टीका कीनी, जयसेन ने व्याख्या दीनी ॥ २१ ॥","टोडरमल और बनारसी दासा, कुंदकुंद वचनों पर विश्वासा ॥ २२ ॥","गुरुवर विद्यासागर ध्यावें, कुंदकुंद की जय जय गावें ॥ २३ ॥"]},{lines:["समयसार का पाठ सुनाओ, भव-भव के संताप मिटाओ ॥ २४ ॥","जो चालीसा चालीस दिन गावे, ज्ञान-सिंधु में गोता लावे ॥ २५ ॥","विद्या बुद्धि विवेक बढ़ावे, आत्म-शांति जीवन में पावे ॥ २६ ॥","रोग-दोष सब दूर नसावे, गुरु-चरणों में जो सिर नावे ॥ २७ ॥"]},{lines:["घर में सुख-शांति बरसाओ, धर्म-मार्ग पर हमें चलाओ ॥ २८ ॥","मैं अज्ञान शरण में आया, कुंदकुंद मुनि ने अपनाया ॥ २९ ॥","अपनी करुणा-दृष्टि बरसाओ, भव-सागर से पार लगाओ ॥ ३० ॥","शुद्धोपयोग की राह दिखाओ, आतम-रस का पान कराओ ॥ ३१ ॥"]},{lines:["कुंदकुंद स्वामी जय जयकारा, वीतरागता का उजियारा ॥ ३२ ॥","जैन धर्म का मूल अधारा, कुंदकुंद वचनों की धारा ॥ ३३ ॥","निसिदिन गुरुवर ध्यान लगाऊँ, जनम-जनम स्वाध्याय रचाऊँ ॥ ३४ ॥","चरण कमल में शीश नवाऊँ, सिद्ध-वधु का वर बन जाऊँ ॥ ३५ ॥"]},{lines:["अहिंसा सत्य दया का सार, कुंदकुंद देव जय जयकार ॥ ३६ ॥","कलिकाल के तीर्थंकर सम, पूजत सुर-नर मुनि अनुपम ॥ ३७ ॥","हाथ जोड़ विनती प्रभु मोरी, काटो कर्म-जाल की डोरी ॥ ३८ ॥","कुंदकुंद चालीसा जो गावे, मोक्ष-महल का पथ वो पावे ॥ ३९ ॥"]},{lines:["जयति जयति कुंदकुंद मुनीशा, पूर्ण करो सेवक अभिलाषा ॥ ४० ॥"]},{lines:["॥ दोहा ॥"]},{lines:["कुंदकुंद गुरु के चरण में, कोटि-कोटि परनाम।","समयसार अमृत दिया, पूरण कीजे काम ॥","शुद्धातम अनुभव करे, मिटे सकल संताप।","कुंदकुंद मुनिराज की, जय बोले निष्पाप ॥"]}]}};export{s as ChalisaData};
